import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise 26 small equal circles on a grid."""
    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(26)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:26]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np
import time
from scipy.optimize import minimize


def _grid_start(rng):
    k = int(np.ceil(np.sqrt(26)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:26]
    pts = np.array(pts, dtype=float)
    pts += rng.normal(0.0, 0.03, size=pts.shape)
    pts = np.clip(pts, 0.0, 1.0)
    return np.column_stack([pts, np.full(26, 0.02)])


def _unpack(z):
    x = z[0::3]
    y = z[1::3]
    r = z[2::3]
    return x, y, r


def _objective(z):
    return -np.sum(z[2::3])


def _constraints(z):
    x, y, r = _unpack(z)
    cons = []
    # inside square
    cons.append(x - r)
    cons.append(1.0 - x - r)
    cons.append(y - r)
    cons.append(1.0 - y - r)
    # pairwise
    n = len(x)
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i] - x[j]
            dy = y[i] - y[j]
            d = np.sqrt(dx * dx + dy * dy)
            cons.append(d - r[i] - r[j])
    return np.concatenate(cons)


def _optimize(z0, maxiter=200):
    bounds = []
    for _ in range(26):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.5))
    cons = {'type': 'ineq', 'fun': _constraints}
    try:
        res = minimize(_objective, z0, method='SLSQP', bounds=bounds,
                       constraints=cons, options={'maxiter': maxiter, 'ftol': 1e-12})
        return res.x
    except Exception:
        return z0


def _feasible_and_score(z):
    x, y, r = _unpack(z)
    if np.any(r <= 0):
        return False, -1.0
    if np.any(x - r < -1e-9) or np.any(x + r > 1 + 1e-9):
        return False, -1.0
    if np.any(y - r < -1e-9) or np.any(y + r > 1 + 1e-9):
        return False, -1.0
    n = len(x)
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i] - x[j]
            dy = y[i] - y[j]
            if np.sqrt(dx * dx + dy * dy) < r[i] + r[j] - 1e-9:
                return False, -1.0
    return True, float(np.sum(r))


def _shrink(z, eps=1e-9):
    z = z.copy()
    r = z[2::3]
    r = np.maximum(r - eps, 1e-7)
    z[2::3] = r
    return z


def construct(budget_seconds, start):
    t0 = time.process_time()
    rng = np.random.default_rng(12345)

    best_z = None
    best_score = -1.0

    # seed with start if available
    if start is not None:
        s = np.asarray(start, dtype=float)
        z = np.empty(78)
        z[0::3] = s[:, 0]
        z[1::3] = s[:, 1]
        z[2::3] = s[:, 2]
        ok, sc = _feasible_and_score(z)
        if ok:
            best_z = z
            best_score = sc

    n_restarts = 8
    for k in range(n_restarts):
        if time.process_time() - t0 > budget_seconds * 0.85:
            break
        z0 = _grid_start(rng)
        z0 = z0.reshape(-1)
        z = _optimize(z0, maxiter=200)
        ok, sc = _feasible_and_score(z)
        if ok and sc > best_score:
            best_score = sc
            best_z = z

    if best_z is None:
        # fall back to base
        k = int(np.ceil(np.sqrt(26)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:26]
        return np.array([[x, y, 0.02] for x, y in pts])

    best_z = _shrink(best_z)
    x, y, r = _unpack(best_z)
    return np.column_stack([x, y, r])

import numpy as np
import time
from scipy.optimize import minimize

N = 26


def _unpack(z):
    return z[0::3], z[1::3], z[2::3]


def _neg_sum(z):
    return -np.sum(z[2::3])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g[2::3] = -1.0
    return g


def _make_constraints():
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def wall(z):
        x, y, r = _unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * N, 3 * N))
        for i in range(N):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[N + i, 3 * i] = -1.0; J[N + i, 3 * i + 2] = -1.0
            J[2 * N + i, 3 * i + 1] = 1.0; J[2 * N + i, 3 * i + 2] = -1.0
            J[3 * N + i, 3 * i + 1] = -1.0; J[3 * N + i, 3 * i + 2] = -1.0
        return J

    def pair(z):
        x, y, r = _unpack(z)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    def pair_jac(z):
        x, y, r = _unpack(z)
        J = np.zeros((len(pairs), 3 * N))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (r[i] + r[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
        return J

    return [
        {'type': 'ineq', 'fun': wall, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair, 'jac': pair_jac},
    ]


def _feasible(x, y, r, tol=1e-7):
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _run_slsqp(z0, cons, maxiter, ftol):
    try:
        res = minimize(_neg_sum, z0, jac=_neg_sum_grad, method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x
    except Exception:
        return z0


def _clean(z):
    x, y, r = _unpack(z)
    r = np.maximum(r, 0.0)
    r = r - 1e-9
    r = np.maximum(r, 1e-9)
    x = np.clip(x, r, 1 - r)
    y = np.clip(y, r, 1 - r)
    return np.column_stack([x, y, r])


def _seed_from_rows(rows, rng):
    pts = []
    nrows = len(rows)
    for j, cnt in enumerate(rows):
        y = (j + 0.5) / nrows
        off = rng.uniform(-0.2, 0.2) / max(cnt, 1)
        for i in range(cnt):
            x = (i + 0.5) / cnt + off
            pts.append((x, y))
    pts = pts[:N]
    while len(pts) < N:
        pts.append((rng.uniform(0.1, 0.9), rng.uniform(0.1, 0.9)))
    arr = np.array([[x, y, 0.04] for x, y in pts])
    arr[:, 0] = np.clip(arr[:, 0], arr[:, 2], 1 - arr[:, 2])
    arr[:, 1] = np.clip(arr[:, 1], arr[:, 2], 1 - arr[:, 2])
    return arr


def _random_composition(total, parts, lo, hi, rng):
    # random composition of total into `parts` integers in [lo, hi]
    for _ in range(200):
        vals = rng.integers(lo, hi + 1, size=parts)
        diff = total - int(vals.sum())
        if diff == 0:
            return list(vals)
        # try to fix
        for _ in range(50):
            idx = rng.integers(0, parts)
            if diff > 0 and vals[idx] < hi:
                vals[idx] += 1; diff -= 1
            elif diff < 0 and vals[idx] > lo:
                vals[idx] -= 1; diff += 1
            if diff == 0:
                return list(vals)
    return None


def construct(budget_seconds, start):
    t0 = time.process_time()
    rng = np.random.default_rng(1234567)
    cons = _make_constraints()

    seeds = []
    n_seeds = 50
    attempts = 0
    while len(seeds) < n_seeds and attempts < 2000:
        attempts += 1
        nrows = int(rng.integers(4, 8))  # 4,5,6,7
        comp = _random_composition(N, nrows, 2, 8, rng)
        if comp is None:
            continue
        seeds.append(_seed_from_rows(comp, rng))

    best_out = None
    best_score = -1.0

    for cand in seeds:
        if time.process_time() - t0 > budget_seconds * 0.90:
            break
        z0 = np.empty(3 * N)
        z0[0::3] = cand[:, 0]
        z0[1::3] = cand[:, 1]
        z0[2::3] = cand[:, 2]
        zres = _run_slsqp(z0, cons, 1200, 1e-10)
        out = _clean(zres)
        if not _feasible(out[:, 0], out[:, 1], out[:, 2]):
            continue
        sc = np.sum(out[:, 2])
        if sc > best_score:
            best_score = sc
            best_out = out

    if best_out is None:
        if start is not None:
            best_out = _clean(np.asarray(start, dtype=float).ravel())
        else:
            k = int(np.ceil(np.sqrt(N)))
            pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
            arr = np.array([[x, y, 0.02] for x, y in pts])
            best_out = _clean(arr.ravel())

    return best_out

