def _radii_from_points(pts):
    # pts: (N,2) in [0,1]. r_i = 0.45 * min(nearest-neighbor dist, wall dist)
    n = pts.shape[0]
    d_nn = np.full(n, np.inf)
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            d = np.hypot(pts[i, 0] - pts[j, 0], pts[i, 1] - pts[j, 1])
            if d < d_nn[i]:
                d_nn[i] = d
    d_w = np.minimum(np.minimum(pts[:, 0], 1 - pts[:, 0]),
                     np.minimum(pts[:, 1], 1 - pts[:, 1]))
    r = 0.45 * np.minimum(d_nn, d_w)
    r = np.maximum(r, 1e-4)
    return r


