from scipy.optimize import minimize, linprog, differential_evolution

N = 26
ROW_COUNTS = [6, 5, 6, 5, 4]


def _unpack(z):
    return z[0::3], z[1::3], z[2::3]


def _neg_sum(z):
    return -np.sum(z[2::3])


def _neg_sum_grad(z):
