    g[2::3] = -1.0
    return g


def _make_constraints():
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def wall(z):
        x, y, r = _unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * N, 3 * N))
        for i in range(N):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[N + i, 3 * i] = -1.0; J[N + i, 3 * i + 2] = -1.0
            J[2 * N + i, 3 * i + 1] = 1.0; J[2 * N + i, 3 * i + 2] = -1.0
            J[3 * N + i, 3 * i + 1] = -1.0; J[3 * N + i, 3 * i + 2] = -1.0
        return J

    def pair(z):
        x, y, r = _unpack(z)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    def pair_jac(z):
        x, y, r = _unpack(z)
        J = np.zeros((len(pairs), 3 * N))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (r[i] + r[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
        return J

    return [
        {'type': 'ineq', 'fun': wall, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair, 'jac': pair_jac},
    ]


def _feasible(x, y, r, tol=1e-7):
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _run_slsqp(z0, cons, maxiter, ftol):
    try:
        res = minimize(_neg_sum, z0, jac=_neg_sum_grad, method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x
    except Exception:
        return z0


def _clean(z):
    x, y, r = _unpack(z)
    r = np.maximum(r, 0.0)
    r = r - 1e-9
    r = np.maximum(r, 1e-9)
    x = np.clip(x, r, 1 - r)
    y = np.clip(y, r, 1 - r)
    return np.column_stack([x, y, r])


def _to_z(arr):
    z = np.empty(3 * N)
    z[0::3] = arr[:, 0]
    z[1::3] = arr[:, 1]
    z[2::3] = arr[:, 2]
    return z


def _rows_to_centers(params):
    """params: 5 row-y, 5 row-x-offsets, shear, scale -> centers (N,2)."""
    ys = params[0:5]
    xoffs = params[5:10]
    shear = params[10]
    scale = params[11]
    centers = np.zeros((N, 2))
    idx = 0
    for ri, cnt in enumerate(ROW_COUNTS):
        y = ys[ri]
        # even spacing across [0,1] with margin, then apply offset
        for k in range(cnt):
            t = (k + 0.5) / cnt
            x = 0.5 + (t - 0.5) * scale + xoffs[ri] + shear * (y - 0.5)
            centers[idx, 0] = x
            centers[idx, 1] = y
            idx += 1
    return centers


def _lp_radii(centers):
    """Maximize sum r subject to wall and pair constraints. Returns radii or None."""
    # variables: r_0..r_{N-1}
    c = -np.ones(N)
    A_ub = []
    b_ub = []
    # wall: r_i <= x_i, r_i <= 1-x_i, r_i <= y_i, r_i <= 1-y_i
    for i in range(N):
        x, y = centers[i]
        for b in (x, 1 - x, y, 1 - y):
            row = np.zeros(N); row[i] = 1.0
            A_ub.append(row); b_ub.append(b - 1e-9)
    # pair: r_i + r_j <= dist - 1e-9
    for i in range(N):
        for j in range(i + 1, N):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(N); row[i] = 1.0; row[j] = 1.0
            A_ub.append(row); b_ub.append(d - 1e-9)
    bounds = [(0, None)] * N
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-9)
    except Exception:
        pass
    return None


def _eval_params(params):
    centers = _rows_to_centers(params)
    # keep centers inside [0,1]
    if np.any(centers < -0.5) or np.any(centers > 1.5):
        return 1e6
    r = _lp_radii(centers)
    if r is None:
        return 1e6
    return -np.sum(r)


def construct(budget_seconds, start):
    t0 = time.process_time()
    if start is not None:
        base = np.asarray(start, dtype=float).copy()
    else:
        k = int(np.ceil(np.sqrt(N)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
        base = np.array([[x, y, 0.02] for x, y in pts])

    base[:, 2] = np.maximum(base[:, 2], 1e-4)
    base[:, 0] = np.clip(base[:, 0], base[:, 2], 1 - base[:, 2])
    base[:, 1] = np.clip(base[:, 1], base[:, 2], 1 - base[:, 2])

    cons = _make_constraints()

    # Polish the start itself
    z0 = _to_z(base)
    best_z = _run_slsqp(z0, cons, 1500, 1e-10)
    best_out = _clean(best_z)
    best_score = np.sum(best_out[:, 2])
    if not _feasible(best_out[:, 0], best_out[:, 1], best_out[:, 2]):
        best_out = _clean(z0)
