    # Reduced-space search
    bounds = [(0.05, 0.95)] * 5 + [(-0.3, 0.3)] * 5 + [(-0.5, 0.5), (0.5, 1.2)]
    try:
        de = differential_evolution(_eval_params, bounds, maxiter=30, popsize=8,
                                    tol=1e-4, seed=12345, polish=False,
                                    init='sobol' if False else 'latinhypercube')
        cand_params = de.x
    except Exception:
        cand_params = np.array([0.1, 0.3, 0.5, 0.7, 0.9, 0, 0, 0, 0, 0, 0, 1.0])

    if time.process_time() - t0 < budget_seconds * 0.8:
        centers = _rows_to_centers(cand_params)
        r = _lp_radii(centers)
        if r is not None:
            arr = np.column_stack([centers, r])
            arr[:, 0] = np.clip(arr[:, 0], arr[:, 2], 1 - arr[:, 2])
            arr[:, 1] = np.clip(arr[:, 1], arr[:, 2], 1 - arr[:, 2])
            zres = _run_slsqp(_to_z(arr), cons, 1500, 1e-10)
            out = _clean(zres)
            if _feasible(out[:, 0], out[:, 1], out[:, 2]):
                sc = np.sum(out[:, 2])
                if sc > best_score:
                    best_score = sc
                    best_out = out

    return best_out

import numpy as np
import time
from scipy.optimize import minimize

N = 26


def _unpack(z):
    return z[0::3], z[1::3], z[2::3]


def _neg_sum(z):
    return -np.sum(z[2::3])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g[2::3] = -1.0
    return g


def _make_constraints():
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def wall(z):
        x, y, r = _unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * N, 3 * N))
        for i in range(N):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[N + i, 3 * i] = -1.0; J[N + i, 3 * i + 2] = -1.0
            J[2 * N + i, 3 * i + 1] = 1.0; J[2 * N + i, 3 * i + 2] = -1.0
            J[3 * N + i, 3 * i + 1] = -1.0; J[3 * N + i, 3 * i + 2] = -1.0
        return J

    def pair(z):
        x, y, r = _unpack(z)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    def pair_jac(z):
        x, y, r = _unpack(z)
        J = np.zeros((len(pairs), 3 * N))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (r[i] + r[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
        return J

    return [
        {'type': 'ineq', 'fun': wall, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair, 'jac': pair_jac},
    ]


def _feasible(x, y, r, tol=1e-7):
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _run_slsqp(z0, cons, maxiter, ftol):
    try:
        res = minimize(_neg_sum, z0, jac=_neg_sum_grad, method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x
    except Exception:
        return z0


def _clean(z):
    x, y, r = _unpack(z)
    r = np.maximum(r, 0.0)
    r = r - 1e-9
    r = np.maximum(r, 1e-9)
    x = np.clip(x, r, 1 - r)
    y = np.clip(y, r, 1 - r)
    return np.column_stack([x, y, r])


def _to_z(arr):
    z = np.empty(3 * N)
    z[0::3] = arr[:, 0]
    z[1::3] = arr[:, 1]
    z[2::3] = arr[:, 2]
    return z


def _compositions(total, parts, lo, hi):
    """All tuples of length `parts` summing to total with each in [lo, hi]."""
    if parts == 1:
        if lo <= total <= hi:
            yield (total,)
        return
    for v in range(lo, hi + 1):
        rem = total - v
        if rem < lo * (parts - 1) or rem > hi * (parts - 1):
            continue
        for rest in _compositions(rem, parts - 1, lo, hi):
            yield (v,) + rest


def _row_seed(counts, rng):
    """Build a seed with given row counts. y evenly spaced, x evenly spaced per row."""
    rows = len(counts)
    pts = []
    for k, c in enumerate(counts):
        y = (k + 0.5) / rows
        offset = rng.uniform(-0.25, 0.25) / c
        for i in range(c):
            x = (i + 0.5) / c + offset
            pts.append((x, y))
    arr = np.array([[x, y, 0.04] for x, y in pts[:N]])
    arr[:, 0] = np.clip(arr[:, 0], arr[:, 2], 1 - arr[:, 2])
    arr[:, 1] = np.clip(arr[:, 1], arr[:, 2], 1 - arr[:, 2])
    return arr


def construct(budget_seconds, start):
    t0 = time.process_time()
    cons = _make_constraints()
    rng = np.random.default_rng(13579)

    # Build the list of row compositions: 4 rows (5-8 each) and 6 rows (3-5 each)
    comps4 = list(_compositions(N, 4, 5, 8))
    comps6 = list(_compositions(N, 6, 3, 5))
    all_comps = comps4 + comps6

    # 200 seeds total: sample with repetition if fewer compositions
    n_seeds = 200
    seeds = []
    for s in range(n_seeds):
        counts = all_comps[s % len(all_comps)]
        seeds.append(_row_seed(counts, rng))

    best_out = None
    best_score = -1.0

    # Time budget: leave margin. Each SLSQP ~ tens of ms.
    deadline = budget_seconds * 0.85

    for s in range(n_seeds):
        if time.process_time() - t0 > deadline:
            break
        seed = seeds[s]
        zres = _run_slsqp(_to_z(seed), cons, 1500, 1e-10)
        out = _clean(zres)
        if _feasible(out[:, 0], out[:, 1], out[:, 2]):
            sc = np.sum(out[:, 2])
            if sc > best_score:
                best_score = sc
                best_out = out

    # Fallback: if nothing feasible (shouldn't happen), return start or a safe grid
    if best_out is None:
        if start is not None:
            best_out = np.asarray(start, dtype=float).copy()
        else:
            k = int(np.ceil(np.sqrt(N)))
            pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
            best_out = np.array([[x, y, 0.02] for x, y in pts])

    # Safety: shrink radii slightly and ensure feasibility
    best_out = best_out.copy()
    best_out[:, 2] = np.maximum(best_out[:, 2] - 1e-9, 1e-9)
    best_out[:, 0] = np.clip(best_out[:, 0], best_out[:, 2], 1 - best_out[:, 2])
    best_out[:, 1] = np.clip(best_out[:, 1], best_out[:, 2], 1 - best_out[:, 2])
    return best_out

