    z[0::3] = arr[:, 0]
    z[1::3] = arr[:, 1]
    z[2::3] = arr[:, 2]
    return z


def _exact_slack(arr):
    """Shrink radii so all constraints hold exactly in floating point."""
    a = arr.copy()
    x = a[:, 0]; y = a[:, 1]; r = a[:, 2]
    # wall slack
    slack = np.minimum(np.minimum(x - r, 1 - x - r),
                       np.minimum(y - r, 1 - y - r))
    # pair slack: (dist - (ri+rj)) / 2
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = math.sqrt(dx * dx + dy * dy)
            s = 0.5 * (d - (r[i] + r[j]))
            if s < slack[i]:
                slack[i] = s
            if s < slack[j]:
                slack[j] = s
    # shrink each radius by its slack (and a tiny epsilon)
    r_new = r + np.minimum(slack, 0.0) - 1e-12
    r_new = np.maximum(r_new, 1e-12)
    a[:, 2] = r_new
    # re-clip centers
    a[:, 0] = np.clip(a[:, 0], a[:, 2], 1 - a[:, 2])
    a[:, 1] = np.clip(a[:, 1], a[:, 2], 1 - a[:, 2])
    return a


def _strict_feasible(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < 0) or np.any(x + r > 1):
        return False
    if np.any(y - r < 0) or np.any(y + r > 1):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                return False
    return True


def construct(budget_seconds, start):
    t0 = time.process_time()
    if start is not None:
        base = np.asarray(start, dtype=float).copy()
    else:
        k = int(np.ceil(np.sqrt(N)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
        base = np.array([[x, y, 0.02] for x, y in pts])

    base[:, 2] = np.maximum(base[:, 2], 1e-4)
    base[:, 0] = np.clip(base[:, 0], base[:, 2], 1 - base[:, 2])
    base[:, 1] = np.clip(base[:, 1], base[:, 2], 1 - base[:, 2])

    cons = _make_constraints()

    def polish(arr):
        z0 = _to_z(arr)
        zr = _run_slsqp(z0, cons, 8000, 1e-15)
        out = _clean(zr)
        out = _exact_slack(out)
        return out

    best_out = polish(base)
    if not _strict_feasible(best_out):
        best_out = _exact_slack(_clean(_to_z(base)))
    best_score = np.sum(best_out[:, 2])

    rng = np.random.default_rng(1234567)

    for _ in range(5):
        if time.process_time() - t0 > budget_seconds * 0.85:
            break
        cand = best_out.copy()
        cand[:, 0] += rng.normal(0, 0.001, size=N)
        cand[:, 1] += rng.normal(0, 0.001, size=N)
        cand[:, 0] = np.clip(cand[:, 0], cand[:, 2], 1 - cand[:, 2])
        cand[:, 1] = np.clip(cand[:, 1], cand[:, 2], 1 - cand[:, 2])
        out = polish(cand)
        if not _strict_feasible(out):
            continue
        sc = np.sum(out[:, 2])
        if sc > best_score:
            best_score = sc
            best_out = out

    return best_out

import numpy as np
import time
import math
from scipy.optimize import minimize

N = 26


def _unpack(z):
    return z[0::3], z[1::3], z[2::3]


def _neg_sum(z):
    return -np.sum(z[2::3])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g[2::3] = -1.0
    return g


def _neg_logsum(z):
    r = z[2::3]
    r = np.maximum(r, 1e-12)
    return -np.sum(np.log(r))


def _neg_logsum_grad(z):
    g = np.zeros_like(z)
    r = np.maximum(z[2::3], 1e-12)
    g[2::3] = -1.0 / r
    return g


def _make_p_fun(p):
    def fun(z):
        r = np.maximum(z[2::3], 1e-12)
        return -np.sum(r ** p)

    def grad(z):
        g = np.zeros_like(z)
        r = np.maximum(z[2::3], 1e-12)
        g[2::3] = -p * r ** (p - 1.0)
        return g

    return fun, grad


def _make_constraints():
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def wall(z):
        x, y, r = _unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * N, 3 * N))
        for i in range(N):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[N + i, 3 * i] = -1.0; J[N + i, 3 * i + 2] = -1.0
            J[2 * N + i, 3 * i + 1] = 1.0; J[2 * N + i, 3 * i + 2] = -1.0
            J[3 * N + i, 3 * i + 1] = -1.0; J[3 * N + i, 3 * i + 2] = -1.0
        return J

    def pair(z):
        x, y, r = _unpack(z)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    def pair_jac(z):
        x, y, r = _unpack(z)
        J = np.zeros((len(pairs), 3 * N))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (r[i] + r[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
        return J

    return [
        {'type': 'ineq', 'fun': wall, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair, 'jac': pair_jac},
    ]


def _feasible(x, y, r, tol=1e-7):
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _run_slsqp(z0, cons, maxiter, ftol, fun=_neg_sum, jac=_neg_sum_grad):
    try:
        res = minimize(fun, z0, jac=jac, method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x
    except Exception:
        return z0


def _clean(z):
    x, y, r = _unpack(z)
    r = np.maximum(r, 0.0)
    r = r - 1e-9
    r = np.maximum(r, 1e-9)
    x = np.clip(x, r, 1 - r)
    y = np.clip(y, r, 1 - r)
    return np.column_stack([x, y, r])


def _to_z(arr):
    z = np.empty(3 * N)
    z[0::3] = arr[:, 0]
    z[1::3] = arr[:, 1]
    z[2::3] = arr[:, 2]
    return z


def _nextafter_down_slack_pass(arr):
    x = arr[:, 0].copy()
    y = arr[:, 1].copy()
    r = arr[:, 2].copy()
    for _ in range(12):
        m = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))
        for i in range(N):
            dx = x[i] - x
            dy = y[i] - y
            d = np.sqrt(dx * dx + dy * dy) - r
            d[i] = np.inf
            mi = np.min(d)
            if mi < m[i]:
                m[i] = mi
        r = np.minimum(r, m)
        r = np.nextafter(r, -np.inf)
        r = np.maximum(r, 1e-12)
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _check_zero_tol(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < 0) or np.any(x + r > 1):
        return False
    if np.any(y - r < 0) or np.any(y + r > 1):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                return False
    return True


def _violating_indices(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    bad = set()
    for i in range(N):
        if r[i] <= 0 or x[i] - r[i] < 0 or x[i] + r[i] > 1 \
                or y[i] - r[i] < 0 or y[i] + r[i] > 1:
            bad.add(i)
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                bad.add(i); bad.add(j)
    return bad


def _repair(arr):
    result = _nextafter_down_slack_pass(arr)
    tries = 0
    while not _check_zero_tol(result) and tries < 30:
        bad = _violating_indices(result)
        if not bad:
            break
        for i in bad:
            result[i, 2] = np.nextafter(result[i, 2], -np.inf)
        result[:, 2] = np.maximum(result[:, 2], 1e-12)
        result = _nextafter_down_slack_pass(result)
        tries += 1
    return result


def construct(budget_seconds, start):
    t0 = time.process_time()
    if start is not None:
        base = np.asarray(start, dtype=float).copy()
    else:
        k = int(np.ceil(np.sqrt(N)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
        base = np.array([[x, y, 0.02] for x, y in pts])

    base[:, 2] = np.maximum(base[:, 2], 1e-4)
    base[:, 0] = np.clip(base[:, 0], base[:, 2], 1 - base[:, 2])
    base[:, 1] = np.clip(base[:, 1], base[:, 2], 1 - base[:, 2])

    cons = _make_constraints()

    # Start from base's result (or a feasible-ish point).
    cur = base.copy()
    cur_score = np.sum(cur[:, 2])

    # p-continuation: p = 0.5, 0.75, 1.0
    for p in (0.5, 0.75, 1.0):
        if time.process_time() - t0 > budget_seconds * 0.75:
            break
        fun, grad = _make_p_fun(p)
        z = _run_slsqp(_to_z(cur), cons, 800, 1e-10, fun=fun, jac=grad)
        cand = _clean(z)
        if _feasible(cand[:, 0], cand[:, 1], cand[:, 2]):
            sc = np.sum(cand[:, 2])
            cur = cand
            cur_score = sc

    # Final SLSQP on sum(r) from the continuation result.
    if time.process_time() - t0 < budget_seconds * 0.85:
        z_final = _run_slsqp(_to_z(cur), cons, 1000, 1e-14)
        arr = np.column_stack([z_final[0::3], z_final[1::3], z_final[2::3]])
        arr = _clean(arr)
        if _feasible(arr[:, 0], arr[:, 1], arr[:, 2]):
            sc = np.sum(arr[:, 2])
            if sc >= cur_score:
                cur = arr
                cur_score = sc

    result = _repair(cur)
    return result

import numpy as np
import time
import math
from scipy.optimize import minimize, root

N = 26


def _unpack(z):
    return z[0::3], z[1::3], z[2::3]


def _neg_sum(z):
    return -np.sum(z[2::3])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g[2::3] = -1.0
    return g


def _neg_logsum(z):
    r = z[2::3]
    r = np.maximum(r, 1e-12)
    return -np.sum(np.log(r))


def _neg_logsum_grad(z):
    g = np.zeros_like(z)
    r = np.maximum(z[2::3], 1e-12)
    g[2::3] = -1.0 / r
    return g


def _make_constraints():
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def wall(z):
        x, y, r = _unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * N, 3 * N))
        for i in range(N):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[N + i, 3 * i] = -1.0; J[N + i, 3 * i + 2] = -1.0
            J[2 * N + i, 3 * i + 1] = 1.0; J[2 * N + i, 3 * i + 2] = -1.0
            J[3 * N + i, 3 * i + 1] = -1.0; J[3 * N + i, 3 * i + 2] = -1.0
        return J

    def pair(z):
        x, y, r = _unpack(z)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    def pair_jac(z):
        x, y, r = _unpack(z)
        J = np.zeros((len(pairs), 3 * N))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (r[i] + r[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
        return J

    return [
        {'type': 'ineq', 'fun': wall, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair, 'jac': pair_jac},
    ]


def _feasible(x, y, r, tol=1e-7):
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _run_slsqp(z0, cons, maxiter, ftol, fun=_neg_sum, jac=_neg_sum_grad):
    try:
        res = minimize(fun, z0, jac=jac, method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x
    except Exception:
        return z0


def _clean(z):
    x, y, r = _unpack(z)
    r = np.maximum(r, 0.0)
    r = r - 1e-9
    r = np.maximum(r, 1e-9)
    x = np.clip(x, r, 1 - r)
    y = np.clip(y, r, 1 - r)
    return np.column_stack([x, y, r])


def _to_z(arr):
    z = np.empty(3 * N)
    z[0::3] = arr[:, 0]
    z[1::3] = arr[:, 1]
    z[2::3] = arr[:, 2]
    return z


def _exact_slack_pass(arr, eps=1e-14):
    x = arr[:, 0].copy()
    y = arr[:, 1].copy()
    r = arr[:, 2].copy()
    for _ in range(10):
        m = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))
        for i in range(N):
            dx = x[i] - x
            dy = y[i] - y
            d = np.sqrt(dx * dx + dy * dy) - r
            d[i] = np.inf
            mi = np.min(d)
            if mi < m[i]:
                m[i] = mi
        r = np.minimum(r, m - eps)
        r = np.maximum(r, 1e-12)
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _nextafter_down_slack_pass(arr):
    x = arr[:, 0].copy()
    y = arr[:, 1].copy()
    r = arr[:, 2].copy()
    for _ in range(12):
        m = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))
        for i in range(N):
            dx = x[i] - x
            dy = y[i] - y
            d = np.sqrt(dx * dx + dy * dy) - r
            d[i] = np.inf
            mi = np.min(d)
            if mi < m[i]:
                m[i] = mi
        r = np.minimum(r, m)
        r = np.nextafter(r, -np.inf)
        r = np.maximum(r, 1e-12)
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _check_zero_tol(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < 0) or np.any(x + r > 1):
        return False
    if np.any(y - r < 0) or np.any(y + r > 1):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                return False
    return True


def _violating_indices(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    bad = set()
    for i in range(N):
        if r[i] <= 0 or x[i] - r[i] < 0 or x[i] + r[i] > 1 \
                or y[i] - r[i] < 0 or y[i] + r[i] > 1:
            bad.add(i)
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                bad.add(i); bad.add(j)
    return bad


def _repair(arr):
    result = _nextafter_down_slack_pass(arr)
    tries = 0
    while not _check_zero_tol(result) and tries < 30:
        bad = _violating_indices(result)
        if not bad:
            break
        for i in bad:
            result[i, 2] = np.nextafter(result[i, 2], -np.inf)
        result[:, 2] = np.maximum(result[:, 2], 1e-12)
        result = _nextafter_down_slack_pass(result)
        tries += 1
    return result


# ---------- Active-set KKT machinery ----------

def _active_constraints(arr, gap_tol=1e-8):
    """Return list of ('wall', i, side) and ('pair', i, j) active constraints."""
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    act = []
    for i in range(N):
        if x[i] - r[i] < gap_tol:
            act.append(('wall', i, 0))  # left
        if 1.0 - x[i] - r[i] < gap_tol:
            act.append(('wall', i, 1))  # right
        if y[i] - r[i] < gap_tol:
            act.append(('wall', i, 2))  # bottom
        if 1.0 - y[i] - r[i] < gap_tol:
            act.append(('wall', i, 3))  # top
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = math.sqrt(dx * dx + dy * dy)
            if d - (r[i] + r[j]) < gap_tol:
                act.append(('pair', i, j))
    return act


def _nearby_none_active_pairs(arr, active_pairs, gap_max=0.03):
    """Return list of non-active pairs with gap < gap_max."""
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    aset = set()
    for a in active_pairs:
        if a[0] == 'pair':
            aset.add((a[1], a[2]))
            aset.add((a[2], a[1]))
    out = []
    for i in range(N):
        for j in range(i + 1, N):
            if (i, j) in aset:
                continue
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = math.sqrt(dx * dx + dy * dy)
            gap = d - (r[i] + r[j])
            if gap < gap_max:
                out.append((i, j, gap))
    out.sort(key=lambda t: t[2])
    return out


def _kkt_residual(z, cons_list, multipliers):
    """Build residual vector F(z, lam) = [grad f + sum lam_k grad g_k ; g_k(z)].
    cons_list: list of callables g_k(z) returning scalar, and their grads.
    We solve for equality g_k = 0 (active constraints).
    Objective: maximize sum r => minimize -sum r, grad = -e_r.
    """
    n = 3 * N
    m = len(cons_list)
    F = np.zeros(n + m)
    # gradient of -sum r
    F[0:n] = 0.0
    F[2::3] = -1.0
    for k, (gfun, ggrad) in enumerate(cons_list):
        gv = gfun(z)
        gv_grad = ggrad(z)
        F[0:n] += multipliers[k] * gv_grad
        F[n + k] = gv
    return F


def _make_active_cons(active):
    """Return list of (gfun, ggrad) for each active constraint, defined as g=0."""
    cons = []
    for a in active:
        if a[0] == 'wall':
            _, i, side = a
            if side == 0:
                def gfun(z, i=i):
                    return z[3 * i] - z[3 * i + 2]
                def ggrad(z, i=i):
                    g = np.zeros(3 * N); g[3 * i] = 1.0; g[3 * i + 2] = -1.0
                    return g
            elif side == 1:
                def gfun(z, i=i):
                    return 1.0 - z[3 * i] - z[3 * i + 2]
                def ggrad(z, i=i):
                    g = np.zeros(3 * N); g[3 * i] = -1.0; g[3 * i + 2] = -1.0
                    return g
            elif side == 2:
                def gfun(z, i=i):
                    return z[3 * i + 1] - z[3 * i + 2]
                def ggrad(z, i=i):
                    g = np.zeros(3 * N); g[3 * i + 1] = 1.0; g[3 * i + 2] = -1.0
                    return g
            else:
                def gfun(z, i=i):
                    return 1.0 - z[3 * i + 1] - z[3 * i + 2]
                def ggrad(z, i=i):
                    g = np.zeros(3 * N); g[3 * i + 1] = -1.0; g[3 * i + 2] = -1.0
                    return g
        else:
            _, i, j = a
            def gfun(z, i=i, j=j):
                dx = z[3 * i] - z[3 * j]; dy = z[3 * i + 1] - z[3 * j + 1]
                rr = z[3 * i + 2] + z[3 * j + 2]
                return dx * dx + dy * dy - rr * rr
            def ggrad(z, i=i, j=j):
                dx = z[3 * i] - z[3 * j]; dy = z[3 * i + 1] - z[3 * j + 1]
                rr = z[3 * i + 2] + z[3 * j + 2]
                g = np.zeros(3 * N)
                g[3 * i] = 2 * dx; g[3 * i + 1] = 2 * dy
                g[3 * j] = -2 * dx; g[3 * j + 1] = -2 * dy
                g[3 * i + 2] = -2 * rr; g[3 * j + 2] = -2 * rr
                return g
        cons.append((gfun, ggrad))
    return cons


def _solve_kkt(z0, active, maxfev=200):
    cons = _make_active_cons(active)
    m = len(cons)
    n = 3 * N
    x0 = np.zeros(n + m)
    x0[0:n] = z0
    # initial multipliers: small positive
    x0[n:] = 1e-3

    def F(v):
        return _kkt_residual(v[0:n], cons, v[n:])

    try:
        sol = root(F, x0, method='hybr', options={'maxfev': maxfev})
        z = sol.x[0:n]
        lam = sol.x[n:]
        return z, lam, sol.success
    except Exception:
        return z0, np.zeros(m), False


def _try_edge_swaps(arr, cons, t0, budget_seconds, best_out, best_score):
    """For each active pair, try swapping with a nearby non-active pair."""
    active = _active_constraints(arr)
    active_pairs = [a for a in active if a[0] == 'pair']
    nearby = _nearby_none_active_pairs(arr, active, gap_max=0.03)
    if not nearby:
        return best_out, best_score

    z_cur = _to_z(arr)
    # Limit work: try a subset
    max_tries = 40
    tried = 0
    for (ai, aj) in active_pairs:
        if tried >= max_tries:
            break
        if time.process_time() - t0 > budget_seconds * 0.92:
            break
        # find a nearby non-active pair involving ai or aj
        cand = None
        for (ni, nj, gap) in nearby:
            if ni == ai or ni == aj or nj == ai or nj == aj:
                cand = (ni, nj)
                break
        if cand is None:
            continue
        tried += 1
        # Build new active set: remove (ai,aj), add cand
        new_active = [a for a in active if not (a[0] == 'pair' and a[1] == ai and a[2] == aj)]
        new_active.append(('pair', cand[0], cand[1]))
        z_sol, lam, ok = _solve_kkt(z_cur, new_active)
        if not ok:
            continue
        # Check multipliers non-negative (for active constraints, lam >= 0 for g=0 with min)
        if np.any(lam < -1e-6):
            continue
        arr_sol = np.column_stack([z_sol[0::3], z_sol[1::3], z_sol[2::3]])
        # SLSQP polish
        z_pol = _run_slsqp(z_sol, cons, 600, 1e-12)
        arr_pol = _clean(z_pol)
        if not _feasible(arr_pol[:, 0], arr_pol[:, 1], arr_pol[:, 2]):
            continue
        sc = np.sum(arr_pol[:, 2])
        if sc > best_score + 1e-10:
            repaired = _repair(arr_pol)
            if _check_zero_tol(repaired):
                sc2 = np.sum(repaired[:, 2])
                if sc2 > best_score:
                    best_out = repaired
                    best_score = sc2
    return best_out, best_score


def construct(budget_seconds, start):
    t0 = time.process_time()
    if start is not None:
        base = np.asarray(start, dtype=float).copy()
    else:
        k = int(np.ceil(np.sqrt(N)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
        base = np.array([[x, y, 0.02] for x, y in pts])

    base[:, 2] = np.maximum(base[:, 2], 1e-4)
    base[:, 0] = np.clip(base[:, 0], base[:, 2], 1 - base[:, 2])
    base[:, 1] = np.clip(base[:, 1], base[:, 2], 1 - base[:, 2])

    cons = _make_constraints()
    z0 = _to_z(base)

    # Start from provided solution: polish it directly (budget is small)
    z_pol = _run_slsqp(z0, cons, 800, 1e-14)
    arr_pol = _clean(z_pol)
    if _feasible(arr_pol[:, 0], arr_pol[:, 1], arr_pol[:, 2]):
        best_out = arr_pol
        best_score = np.sum(arr_pol[:, 2])
    else:
        best_out = base.copy()
        best_score = np.sum(base[:, 2])

    # Also try log-sum phase briefly
    if time.process_time() - t0 < budget_seconds * 0.35:
        z_log = _run_slsqp(z0, cons, 400, 1e-10,
                           fun=_neg_logsum, jac=_neg_logsum_grad)
        arr_log = _clean(z_log)
        if _feasible(arr_log[:, 0], arr_log[:, 1], arr_log[:, 2]):
            sc = np.sum(arr_log[:, 2])
            if sc > best_score:
                best_out = arr_log
                best_score = sc

    # Active-set edge-swap experiment
    if time.process_time() - t0 < budget_seconds * 0.55:
        best_out, best_score = _try_edge_swaps(
            best_out, cons, t0, budget_seconds, best_out, best_score)

    # Final polish
    if time.process_time() - t0 < budget_seconds * 0.90:
        z_final = _run_slsqp(_to_z(best_out), cons, 600, 1e-14)
        arr = np.column_stack([z_final[0::3], z_final[1::3], z_final[2::3]])
        if _feasible(arr[:, 0], arr[:, 1], arr[:, 2]):
            sc = np.sum(arr[:, 2])
            if sc > best_score:
                best_out = arr
                best_score = sc

    result = _repair(best_out)
    return result

