                or y[i] - r[i] < 0 or y[i] + r[i] > 1:
            bad.add(i)
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                bad.add(i); bad.add(j)
    return bad


def _repair(arr):
    result = _nextafter_down_slack_pass(arr)
    tries = 0
    while not _check_zero_tol(result) and tries < 30:
        bad = _violating_indices(result)
        if not bad:
            break
        for i in bad:
            result[i, 2] = np.nextafter(result[i, 2], -np.inf)
        result[:, 2] = np.maximum(result[:, 2], 1e-12)
        result = _nextafter_down_slack_pass(result)
        tries += 1
    return result


def _compositions(total, parts, lo, hi):
    """All tuples of length `parts` summing to `total`, each in [lo, hi]."""
    if parts == 1:
        if lo <= total <= hi:
            yield (total,)
        return
    for first in range(lo, hi + 1):
        rem = total - first
        if rem < lo * (parts - 1) or rem > hi * (parts - 1):
            continue
        for rest in _compositions(rem, parts - 1, lo, hi):
            yield (first,) + rest


def _seed_from_composition(comp):
    """Place rows evenly in y, each row's circles evenly in x with offset."""
    rows = len(comp)
    arr = np.zeros((N, 3))
    k = 0
    for ri, cnt in enumerate(comp):
        yc = (ri + 0.5) / rows
        # offset alternating rows slightly
        off = 0.5 * (ri % 2) / max(cnt, 1)
        for ci in range(cnt):
            xc = (ci + 0.5) / cnt + off * 0.5
            xc = min(max(xc, 0.05), 0.95)
            arr[k] = (xc, yc, 0.04)
            k += 1
    return arr


def construct(budget_seconds, start):
    t0 = time.process_time()
    cons = _make_constraints()

    # Enumerate all 5-row compositions with counts in [3,8]
    comps = list(_compositions(N, 5, 3, 8))

    results = []  # (score, arr)

    # Quick screen: run log-sum then sum SLSQP on each composition with modest iters
    for comp in comps:
        if time.process_time() - t0 > budget_seconds * 0.55:
            break
        seed = _seed_from_composition(comp)
        z0 = _to_z(seed)
        z_log = _run_slsqp(z0, cons, 300, 1e-9,
                           fun=_neg_logsum, jac=_neg_logsum_grad)
        arr_log = _clean(z_log)
        z_sum = _run_slsqp(_to_z(arr_log), cons, 400, 1e-9)
        out = _clean(z_sum)
        if not _feasible(out[:, 0], out[:, 1], out[:, 2]):
            out = arr_log
            if not _feasible(out[:, 0], out[:, 1], out[:, 2]):
                continue
        sc = np.sum(out[:, 2])
        results.append((sc, out, comp))

    if not results:
        # fallback: use start or grid
        if start is not None:
            base = np.asarray(start, dtype=float).copy()
        else:
            k = int(np.ceil(np.sqrt(N)))
            pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
            base = np.array([[x, y, 0.02] for x, y in pts])
        return _repair(base)

    results.sort(key=lambda t: -t[0])
    best_score, best_out, _ = results[0]

    # Refine the best few with more iterations
    top = results[:4]
    for sc, out, comp in top:
        if time.process_time() - t0 > budget_seconds * 0.85:
            break
        z = _run_slsqp(_to_z(out), cons, 1500, 1e-12)
        cand = _clean(z)
        if _feasible(cand[:, 0], cand[:, 1], cand[:, 2]):
            cs = np.sum(cand[:, 2])
            if cs > best_score:
                best_score = cs
                best_out = cand

    # Final polish
    if time.process_time() - t0 < budget_seconds * 0.92:
        z = _run_slsqp(_to_z(best_out), cons, 800, 1e-14)
        cand = _clean(z)
        if _feasible(cand[:, 0], cand[:, 1], cand[:, 2]):
            cs = np.sum(cand[:, 2])
            if cs > best_score:
                best_score = cs
                best_out = cand

    result = _repair(best_out)
    return result

import numpy as np
import time
import math
from scipy.optimize import minimize

N = 26


def _unpack(z):
    return z[0::3], z[1::3], z[2::3]


def _neg_sum(z):
    return -np.sum(z[2::3])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g[2::3] = -1.0
    return g


def _neg_logsum(z):
    r = z[2::3]
    r = np.maximum(r, 1e-12)
    return -np.sum(np.log(r))


def _neg_logsum_grad(z):
    g = np.zeros_like(z)
    r = np.maximum(z[2::3], 1e-12)
    g[2::3] = -1.0 / r
    return g


def _make_constraints():
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def wall(z):
        x, y, r = _unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * N, 3 * N))
        for i in range(N):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[N + i, 3 * i] = -1.0; J[N + i, 3 * i + 2] = -1.0
            J[2 * N + i, 3 * i + 1] = 1.0; J[2 * N + i, 3 * i + 2] = -1.0
            J[3 * N + i, 3 * i + 1] = -1.0; J[3 * N + i, 3 * i + 2] = -1.0
        return J

    def pair(z):
        x, y, r = _unpack(z)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    def pair_jac(z):
        x, y, r = _unpack(z)
        J = np.zeros((len(pairs), 3 * N))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (r[i] + r[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
        return J

    return [
        {'type': 'ineq', 'fun': wall, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair, 'jac': pair_jac},
    ]


def _feasible(x, y, r, tol=1e-7):
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _run_slsqp(z0, cons, maxiter, ftol, fun=_neg_sum, jac=_neg_sum_grad):
    try:
        res = minimize(fun, z0, jac=jac, method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x
    except Exception:
        return z0


def _clean(z):
    x, y, r = _unpack(z)
    r = np.maximum(r, 0.0)
    r = r - 1e-9
    r = np.maximum(r, 1e-9)
    x = np.clip(x, r, 1 - r)
    y = np.clip(y, r, 1 - r)
    return np.column_stack([x, y, r])


def _to_z(arr):
    z = np.empty(3 * N)
    z[0::3] = arr[:, 0]
    z[1::3] = arr[:, 1]
    z[2::3] = arr[:, 2]
    return z


def _nextafter_down_slack_pass(arr):
    x = arr[:, 0].copy()
    y = arr[:, 1].copy()
    r = arr[:, 2].copy()
    for _ in range(12):
        m = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))
        for i in range(N):
            dx = x[i] - x
            dy = y[i] - y
            d = np.sqrt(dx * dx + dy * dy) - r
            d[i] = np.inf
            mi = np.min(d)
            if mi < m[i]:
                m[i] = mi
        r = np.minimum(r, m)
        r = np.nextafter(r, -np.inf)
        r = np.maximum(r, 1e-12)
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _check_zero_tol(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < 0) or np.any(x + r > 1):
        return False
    if np.any(y - r < 0) or np.any(y + r > 1):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                return False
    return True


def _violating_indices(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    bad = set()
    for i in range(N):
        if r[i] <= 0 or x[i] - r[i] < 0 or x[i] + r[i] > 1 \
                or y[i] - r[i] < 0 or y[i] + r[i] > 1:
            bad.add(i)
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                bad.add(i); bad.add(j)
    return bad


def _repair(arr):
    result = _nextafter_down_slack_pass(arr)
    tries = 0
    while not _check_zero_tol(result) and tries < 30:
        bad = _violating_indices(result)
        if not bad:
            break
        for i in bad:
            result[i, 2] = np.nextafter(result[i, 2], -np.inf)
        result[:, 2] = np.maximum(result[:, 2], 1e-12)
        result = _nextafter_down_slack_pass(result)
        tries += 1
    return result


def _make_central_seeds():
    """Seeds: one large central circle + 25 small satellites on rings."""
    seeds = []
    # Two concentric rings: inner ~10, outer ~15
    for Rc in (0.16, 0.18, 0.20):
        for rsmall in (0.025, 0.032, 0.040):
            for inner_frac in (0.35, 0.45, 0.55):
                pts = [(0.5, 0.5, Rc)]
                # inner ring
                n_in = 10
                r_in = inner_frac
                for k in range(n_in):
                    a = 2 * math.pi * k / n_in
                    pts.append((0.5 + r_in * math.cos(a),
                                0.5 + r_in * math.sin(a), rsmall))
                # outer ring
                n_out = 15
                r_out = 0.5 - rsmall - 0.01
                for k in range(n_out):
                    a = 2 * math.pi * k / n_out + math.pi / n_out
                    pts.append((0.5 + r_out * math.cos(a),
                                0.5 + r_out * math.sin(a), rsmall))
                seeds.append(np.array(pts[:N]))
    # Hex ring: center + 2 hex rings
    for Rc in (0.16, 0.18, 0.20):
        for rsmall in (0.025, 0.032, 0.040):
            pts = [(0.5, 0.5, Rc)]
            # hex ring 1: 6 circles
            d1 = 0.5 - rsmall - 0.01
            for k in range(6):
                a = math.pi / 3 * k
                pts.append((0.5 + d1 * math.cos(a), 0.5 + d1 * math.sin(a), rsmall))
            # hex ring 2: 12 circles
            d2 = 0.5 - rsmall - 0.01
            for k in range(12):
                a = math.pi / 6 + math.pi / 6 * k
                pts.append((0.5 + d2 * math.cos(a), 0.5 + d2 * math.sin(a), rsmall))
            # remaining 6 in a middle ring
            for k in range(6):
                a = math.pi / 3 * k + math.pi / 6
                pts.append((0.5 + 0.28 * math.cos(a), 0.5 + 0.28 * math.sin(a), rsmall))
            seeds.append(np.array(pts[:N]))
    # NEW balanced central-dominant family
    for Rc in (0.10, 0.12, 0.14, 0.16):
        for rsmall in (0.05, 0.07, 0.09):
            for (n_in, n_out) in ((8, 17), (10, 15), (12, 13)):
                for r_in in (0.18, 0.24, 0.30):
                    r_out = 0.5 - rsmall - 0.01
                    for rot in (0.0, math.pi / n_in):
                        pts = [(0.5, 0.5, Rc)]
                        for k in range(n_in):
                            a = 2 * math.pi * k / n_in + rot
                            pts.append((0.5 + r_in * math.cos(a),
                                        0.5 + r_in * math.sin(a), rsmall))
                        for k in range(n_out):
                            a = 2 * math.pi * k / n_out + math.pi / n_out
                            pts.append((0.5 + r_out * math.cos(a),
                                        0.5 + r_out * math.sin(a), rsmall))
                        seeds.append(np.array(pts[:N]))
    return seeds


def construct(budget_seconds, start):
    t0 = time.process_time()
    seeds = _make_central_seeds()
    cons = _make_constraints()

    best_out = None
    best_score = -np.inf

    # Seed with start if provided
    if start is not None:
        try:
            s = np.array(start, dtype=float)
            if s.shape == (N, 3):
                sc = np.sum(s[:, 2])
                if _feasible(s[:, 0], s[:, 1], s[:, 2]):
                    best_out = s.copy()
                    best_score = sc
        except Exception:
            pass

    for si, base in enumerate(seeds):
        if time.process_time() - t0 > budget_seconds * 0.75:
            break
        base = base.copy()
        base[:, 2] = np.maximum(base[:, 2], 1e-4)
        base[:, 0] = np.clip(base[:, 0], base[:, 2], 1 - base[:, 2])
        base[:, 1] = np.clip(base[:, 1], base[:, 2], 1 - base[:, 2])
        z0 = _to_z(base)

        # Phase 1: log-sum for balance
        z_log = _run_slsqp(z0, cons, 800, 1e-12,
                           fun=_neg_logsum, jac=_neg_logsum_grad)
        arr_log = _clean(z_log)

        # Phase 2: sum
        z_sum = _run_slsqp(_to_z(arr_log), cons, 1200, 1e-10)
        out = _clean(z_sum)
        if _feasible(out[:, 0], out[:, 1], out[:, 2]):
            sc = np.sum(out[:, 2])
            if sc > best_score:
                best_score = sc
                best_out = out

        # Direct sum from seed
        z_direct = _run_slsqp(z0, cons, 1200, 1e-10)
        out_d = _clean(z_direct)
        if _feasible(out_d[:, 0], out_d[:, 1], out_d[:, 2]):
            sc = np.sum(out_d[:, 2])
            if sc > best_score:
                best_score = sc
                best_out = out_d

    if best_out is None:
        k = int(np.ceil(np.sqrt(N)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
        best_out = np.array([[x, y, 0.02] for x, y in pts])

    # Final polish
    if time.process_time() - t0 < budget_seconds * 0.90:
        z_final = _run_slsqp(_to_z(best_out), cons, 800, 1e-14)
        arr_c = _clean(z_final)
        if _feasible(arr_c[:, 0], arr_c[:, 1], arr_c[:, 2]):
            if np.sum(arr_c[:, 2]) >= best_score:
                best_out = arr_c

    result = _repair(best_out)
    return result

