                r_out = 0.5 - rsmall - 0.01
                for k in range(n_out):
                    a = 2 * math.pi * k / n_out + math.pi / n_out
                    pts.append((0.5 + r_out * math.cos(a),
                                0.5 + r_out * math.sin(a), rsmall))
                seeds.append(np.array(pts[:N]))
    for Rc in (0.16, 0.18, 0.20):
        for rsmall in (0.025, 0.032, 0.040):
            pts = [(0.5, 0.5, Rc)]
            d1 = 0.5 - rsmall - 0.01
            for k in range(6):
                a = math.pi / 3 * k
                pts.append((0.5 + d1 * math.cos(a), 0.5 + d1 * math.sin(a), rsmall))
            d2 = 0.5 - rsmall - 0.01
            for k in range(12):
                a = math.pi / 6 + math.pi / 6 * k
                pts.append((0.5 + d2 * math.cos(a), 0.5 + d2 * math.sin(a), rsmall))
            for k in range(6):
                a = math.pi / 3 * k + math.pi / 6
                pts.append((0.5 + 0.28 * math.cos(a), 0.5 + 0.28 * math.sin(a), rsmall))
            seeds.append(np.array(pts[:N]))
    return seeds


def _lp_radii(x, y):
    """Maximize sum(r) subject to wall and pair constraints, fixed centers."""
    n = N
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    # r_i <= min wall distance
    for i in range(n):
        row = np.zeros(n)
        row[i] = 1.0
        A_ub.append(row)
        b_ub.append(min(x[i], 1.0 - x[i], y[i], 1.0 - y[i]))
    # r_i + r_j <= dist
    for i in range(n):
        for j in range(i + 1, n):
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(math.hypot(x[i] - x[j], y[i] - y[j]))
    bounds = [(0, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-12)
    except Exception:
        pass
    return None


def _exact_clean(arr):
    """Shrink radii by tiny amount and clip to guarantee zero-tolerance feasibility."""
    x = arr[:, 0].copy()
    y = arr[:, 1].copy()
    r = arr[:, 2].copy()
    # iterative shrink to satisfy all constraints exactly
    for _ in range(50):
        ok = True
        # walls
        for i in range(N):
            m = min(x[i], 1.0 - x[i], y[i], 1.0 - y[i])
            if r[i] > m:
                r[i] = np.nextafter(m, -np.inf)
                ok = False
        # pairs
        for i in range(N):
            for j in range(i + 1, N):
                d = math.hypot(x[i] - x[j], y[i] - y[j])
                if r[i] + r[j] > d:
                    excess = (r[i] + r[j] - d) * 0.5 + 1e-15
                    r[i] = max(r[i] - excess, 1e-12)
                    r[j] = max(r[j] - excess, 1e-12)
                    ok = False
        if ok:
            break
    # final nextafter safety
    r = np.nextafter(r, -np.inf)
    r = np.maximum(r, 1e-12)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def construct(budget_seconds, start):
    t0 = time.process_time()
    seeds = _make_central_seeds()
    cons = _make_constraints()

    best_out = None
    best_score = -np.inf

    for si, base in enumerate(seeds):
        if time.process_time() - t0 > budget_seconds * 0.75:
            break
        base = base.copy()
        base[:, 2] = np.maximum(base[:, 2], 1e-4)
        base[:, 0] = np.clip(base[:, 0], base[:, 2], 1 - base[:, 2])
        base[:, 1] = np.clip(base[:, 1], base[:, 2], 1 - base[:, 2])
        z0 = _to_z(base)

        z_log = _run_slsqp(z0, cons, 800, 1e-12,
                           fun=_neg_logsum, jac=_neg_logsum_grad)
        arr_log = _clean(z_log)

        z_sum = _run_slsqp(_to_z(arr_log), cons, 1200, 1e-10)
        out = _clean(z_sum)
        if _feasible(out[:, 0], out[:, 1], out[:, 2]):
            sc = np.sum(out[:, 2])
            if sc > best_score:
                best_score = sc
                best_out = out

        z_direct = _run_slsqp(z0, cons, 1200, 1e-10)
        out_d = _clean(z_direct)
        if _feasible(out_d[:, 0], out_d[:, 1], out_d[:, 2]):
            sc = np.sum(out_d[:, 2])
            if sc > best_score:
                best_score = sc
                best_out = out_d

    if best_out is None:
        k = int(np.ceil(np.sqrt(N)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
        best_out = np.array([[x, y, 0.02] for x, y in pts])

    if time.process_time() - t0 < budget_seconds * 0.90:
        z_final = _run_slsqp(_to_z(best_out), cons, 800, 1e-14)
        arr_c = _clean(z_final)
        if _feasible(arr_c[:, 0], arr_c[:, 1], arr_c[:, 2]):
            if np.sum(arr_c[:, 2]) >= best_score:
                best_out = arr_c

    # NEW: LP radii solve on best centers, then SLSQP polish
    if time.process_time() - t0 < budget_seconds * 0.95:
        x = best_out[:, 0].copy()
        y = best_out[:, 1].copy()
        r_lp = _lp_radii(x, y)
        if r_lp is not None:
            arr_lp = np.column_stack([x, y, r_lp])
            arr_lp = _exact_clean(arr_lp)
            z_lp = _to_z(arr_lp)
            z_pol = _run_slsqp(z_lp, cons, 800, 1e-14)
            arr_pol = _clean(z_pol)
            if _feasible(arr_pol[:, 0], arr_pol[:, 1], arr_pol[:, 2]):
                if np.sum(arr_pol[:, 2]) >= best_score:
                    best_score = np.sum(arr_pol[:, 2])
                    best_out = arr_pol
            # also compare LP-only result
            if np.sum(arr_lp[:, 2]) > best_score:
                best_score = np.sum(arr_lp[:, 2])
                best_out = arr_lp

    result = _repair(best_out)
    result = _exact_clean(result)
    return result

import numpy as np
import time
import math
from scipy.optimize import minimize

N = 26


def _unpack(z):
    return z[0::3], z[1::3], z[2::3]


def _neg_sum(z):
    return -np.sum(z[2::3])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g[2::3] = -1.0
    return g


def _neg_logsum(z):
    r = z[2::3]
    r = np.maximum(r, 1e-12)
    return -np.sum(np.log(r))


def _neg_logsum_grad(z):
    g = np.zeros_like(z)
    r = np.maximum(z[2::3], 1e-12)
    g[2::3] = -1.0 / r
    return g


def _make_constraints():
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def wall(z):
        x, y, r = _unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * N, 3 * N))
        for i in range(N):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[N + i, 3 * i] = -1.0; J[N + i, 3 * i + 2] = -1.0
            J[2 * N + i, 3 * i + 1] = 1.0; J[2 * N + i, 3 * i + 2] = -1.0
            J[3 * N + i, 3 * i + 1] = -1.0; J[3 * N + i, 3 * i + 2] = -1.0
        return J

    def pair(z):
        x, y, r = _unpack(z)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    def pair_jac(z):
        x, y, r = _unpack(z)
        J = np.zeros((len(pairs), 3 * N))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (r[i] + r[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
        return J

    return [
        {'type': 'ineq', 'fun': wall, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair, 'jac': pair_jac},
    ]


def _feasible(x, y, r, tol=1e-7):
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _run_slsqp(z0, cons, maxiter, ftol, fun=_neg_sum, jac=_neg_sum_grad):
    try:
        res = minimize(fun, z0, jac=jac, method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x
    except Exception:
        return z0


def _clean(z):
    x, y, r = _unpack(z)
    r = np.maximum(r, 0.0)
    r = r - 1e-9
    r = np.maximum(r, 1e-9)
    x = np.clip(x, r, 1 - r)
    y = np.clip(y, r, 1 - r)
    return np.column_stack([x, y, r])


def _to_z(arr):
    z = np.empty(3 * N)
    z[0::3] = arr[:, 0]
    z[1::3] = arr[:, 1]
    z[2::3] = arr[:, 2]
    return z


def _nextafter_down_slack_pass(arr):
    x = arr[:, 0].copy()
    y = arr[:, 1].copy()
    r = arr[:, 2].copy()
    for _ in range(12):
        m = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))
        for i in range(N):
            dx = x[i] - x
            dy = y[i] - y
            d = np.sqrt(dx * dx + dy * dy) - r
            d[i] = np.inf
            mi = np.min(d)
            if mi < m[i]:
                m[i] = mi
        r = np.minimum(r, m)
        r = np.nextafter(r, -np.inf)
        r = np.maximum(r, 1e-12)
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _check_zero_tol(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < 0) or np.any(x + r > 1):
        return False
    if np.any(y - r < 0) or np.any(y + r > 1):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                return False
    return True


def _violating_indices(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    bad = set()
    for i in range(N):
        if r[i] <= 0 or x[i] - r[i] < 0 or x[i] + r[i] > 1 \
                or y[i] - r[i] < 0 or y[i] + r[i] > 1:
            bad.add(i)
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                bad.add(i); bad.add(j)
    return bad


def _repair(arr):
    result = _nextafter_down_slack_pass(arr)
    tries = 0
    while not _check_zero_tol(result) and tries < 30:
        bad = _violating_indices(result)
        if not bad:
            break
        for i in bad:
            result[i, 2] = np.nextafter(result[i, 2], -np.inf)
        result[:, 2] = np.maximum(result[:, 2], 1e-12)
        result = _nextafter_down_slack_pass(result)
        tries += 1
    return result


def _make_two_dominant_seeds():
    """Seeds with two large circles + 24 small satellites."""
    seeds = []
    # Two large circle placements
    big_positions = [
        ((0.35, 0.5), (0.65, 0.5)),
        ((0.5, 0.35), (0.5, 0.65)),
    ]
    for (p1, p2) in big_positions:
        for Rbig in (0.11, 0.12, 0.13):
            for rsmall in (0.035, 0.042, 0.05):
                # Variant A: two rings around each big circle
                pts = [(p1[0], p1[1], Rbig), (p2[0], p2[1], Rbig)]
                # ring around each big circle: 6 each
                for (cx, cy) in (p1, p2):
                    for k in range(6):
                        a = math.pi / 3 * k
                        d = Rbig + rsmall + 0.005
                        pts.append((cx + d * math.cos(a),
                                    cy + d * math.sin(a), rsmall))
                # remaining 12 on outer boundary ring
                for k in range(12):
                    a = 2 * math.pi * k / 12 + math.pi / 12
                    rr = 0.5 - rsmall - 0.005
                    pts.append((0.5 + rr * math.cos(a),
                                0.5 + rr * math.sin(a), rsmall))
                seeds.append(np.array(pts[:N]))

                # Variant B: two concentric rings around midpoint
                pts = [(p1[0], p1[1], Rbig), (p2[0], p2[1], Rbig)]
                mx = 0.5 * (p1[0] + p2[0]); my = 0.5 * (p1[1] + p2[1])
                # inner ring 8
                for k in range(8):
                    a = 2 * math.pi * k / 8
                    d = 0.22
                    pts.append((mx + d * math.cos(a),
                                my + d * math.sin(a), rsmall))
                # outer ring 16
                for k in range(16):
                    a = 2 * math.pi * k / 16 + math.pi / 16
                    rr = 0.5 - rsmall - 0.005
                    pts.append((0.5 + rr * math.cos(a),
                                0.5 + rr * math.sin(a), rsmall))
                seeds.append(np.array(pts[:N]))

                # Variant C: hex packing around the pair
                pts = [(p1[0], p1[1], Rbig), (p2[0], p2[1], Rbig)]
                # hex lattice fill
                d = 2 * rsmall + 0.002
                cand = []
                for iy in range(-8, 9):
                    for ix in range(-8, 9):
                        cx = 0.5 + ix * d
                        cy = 0.5 + iy * d * math.sqrt(3) / 2 + (ix % 2) * d / 2
                        if 0.02 < cx < 0.98 and 0.02 < cy < 0.98:
                            cand.append((cx, cy))
                cand.sort(key=lambda p: (p[0] - 0.5) ** 2 + (p[1] - 0.5) ** 2)
                for (cx, cy) in cand:
                    if len(pts) >= N:
                        break
                    ok = True
                    for (qx, qy, qr) in pts:
                        if (cx - qx) ** 2 + (cy - qy) ** 2 < (qr + rsmall) ** 2 * 0.95:
                            ok = False
                            break
                    if ok:
                        pts.append((cx, cy, rsmall))
                while len(pts) < N:
                    pts.append((0.5, 0.5, rsmall))
                seeds.append(np.array(pts[:N]))
    return seeds


def construct(budget_seconds, start):
    t0 = time.process_time()
    seeds = _make_two_dominant_seeds()
    cons = _make_constraints()

    best_out = None
    best_score = -np.inf

    # Consider start as one candidate too
    if start is not None:
        try:
            s = np.array(start, dtype=float)
            if s.shape == (N, 3):
                sc = np.sum(s[:, 2])
                if _feasible(s[:, 0], s[:, 1], s[:, 2]):
                    best_out = s.copy()
                    best_score = sc
        except Exception:
            pass

    for si, base in enumerate(seeds):
        if time.process_time() - t0 > budget_seconds * 0.75:
            break
        base = base.copy()
        base[:, 2] = np.maximum(base[:, 2], 1e-4)
        base[:, 0] = np.clip(base[:, 0], base[:, 2], 1 - base[:, 2])
        base[:, 1] = np.clip(base[:, 1], base[:, 2], 1 - base[:, 2])
        z0 = _to_z(base)

        # Phase 1: log-sum for balance
        z_log = _run_slsqp(z0, cons, 800, 1e-12,
                           fun=_neg_logsum, jac=_neg_logsum_grad)
        arr_log = _clean(z_log)

        # Phase 2: sum
        z_sum = _run_slsqp(_to_z(arr_log), cons, 1200, 1e-10)
        out = _clean(z_sum)
        if _feasible(out[:, 0], out[:, 1], out[:, 2]):
            sc = np.sum(out[:, 2])
            if sc > best_score:
                best_score = sc
                best_out = out

        # Direct sum from seed
        z_direct = _run_slsqp(z0, cons, 1200, 1e-10)
        out_d = _clean(z_direct)
        if _feasible(out_d[:, 0], out_d[:, 1], out_d[:, 2]):
            sc = np.sum(out_d[:, 2])
            if sc > best_score:
                best_score = sc
                best_out = out_d

    if best_out is None:
        k = int(np.ceil(np.sqrt(N)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
        best_out = np.array([[x, y, 0.02] for x, y in pts])

    # Final polish
    if time.process_time() - t0 < budget_seconds * 0.90:
        z_final = _run_slsqp(_to_z(best_out), cons, 800, 1e-14)
        arr_c = _clean(z_final)
        if _feasible(arr_c[:, 0], arr_c[:, 1], arr_c[:, 2]):
            if np.sum(arr_c[:, 2]) >= best_score:
                best_out = arr_c

    result = _repair(best_out)
    return result

