def _pair_gaps(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    gaps = {}
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
