        if kind == 0:
            row[3 * i] = 1.0; row[3 * i + 2] = -1.0
        elif kind == 1:
            row[3 * i] = -1.0; row[3 * i + 2] = -1.0
        elif kind == 2:
            row[3 * i + 1] = 1.0; row[3 * i + 2] = -1.0
        else:
            row[3 * i + 1] = -1.0; row[3 * i + 2] = -1.0
        rows.append(row)
    if not rows:
        return np.zeros((0, 3 * N))
    return np.array(rows)


def construct(budget_seconds, start):
    t0 = time.process_time()

    best = None
    best_score = -np.inf

    if start is not None:
        s = np.array(start, dtype=float)
        if s.shape == (N, 3) and _feasible_loose(s):
            s = _exact_clean(s)
            if _check_zero_tol(s):
                best = s
                best_score = float(np.sum(s[:, 2]))

    if best is None:
        best = _exact_clean(_fallback())
        best_score = float(np.sum(best[:, 2]))

    deadline = budget_seconds * 0.85

    # Phase 1: equality-constrained polish of the start's contact graph
    try:
        ap, aw = _find_active(best, tol=1e-9)
        cons_eq = _make_constraints(ap, aw)
        z0 = _to_z(best)
        z = _run_slsqp(z0, cons_eq, 3000, 1e-14)
        arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
        arr = _exact_clean(arr)
        if _check_zero_tol(arr):
            sc = float(np.sum(arr[:, 2]))
            if sc > best_score:
                best = arr
                best_score = sc
    except Exception:
        pass

    # Phase 2: inequality-only SLSQP polish
    if time.process_time() - t0 < deadline:
        try:
            cons = _make_constraints()
            z0 = _to_z(best)
            z = _run_slsqp(z0, cons, 3000, 1e-14)
            arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
            arr = _exact_clean(arr)
            if _check_zero_tol(arr):
                sc = float(np.sum(arr[:, 2]))
                if sc > best_score:
                    best = arr
                    best_score = sc
        except Exception:
            pass

    # Phase 3: small random restarts with equality constraints on current active set
    rng = np.random.default_rng(12345)
    while time.process_time() - t0 < deadline:
        try:
            ap, aw = _find_active(best, tol=1e-9)
            cons_eq = _make_constraints(ap, aw)
            sigma = math.exp(rng.uniform(math.log(1e-4), math.log(1e-2)))
            cand = best.copy()
            cand[:, 0] += rng.normal(0.0, sigma, N)
            cand[:, 1] += rng.normal(0.0, sigma, N)
            cand[:, 2] += rng.normal(0.0, 0.5 * sigma, N)
            cand[:, 2] = np.maximum(cand[:, 2], 1e-6)
            cand[:, 0] = np.clip(cand[:, 0], cand[:, 2], 1.0 - cand[:, 2])
            cand[:, 1] = np.clip(cand[:, 1], cand[:, 2], 1.0 - cand[:, 2])
            z0 = _to_z(cand)
            z = _run_slsqp(z0, cons_eq, 3000, 1e-14)
            arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
            arr = _exact_clean(arr)
            if not _check_zero_tol(arr):
                continue
            sc = float(np.sum(arr[:, 2]))
            if sc > best_score:
                best = arr
                best_score = sc
        except Exception:
            continue

    # Phase 4 (new): nullspace exploration around best
    if time.process_time() - t0 < deadline:
        try:
            ap, aw = _find_active(best, tol=1e-9)
            z_best = _to_z(best)
            A = _active_jacobian(z_best, ap, aw)
            if A.shape[0] > 0:
                # Nullspace via SVD
                U, S, Vt = np.linalg.svd(A, full_matrices=True)
                # rows of Vt correspond to right singular vectors; nullspace = rows with S small
                n_sv = len(S)
                null_rows = [k for k in range(3 * N) if k >= n_sv or S[k] < 1e-10]
                Z = Vt[null_rows].T  # (78, d)
                d = Z.shape[1]
            else:
                Z = np.eye(3 * N)
                d = 3 * N

            if d > 0:
                cons_ineq = _make_constraints()
                rng2 = np.random.default_rng(98765)
                n_trials = 100
                for _ in range(n_trials):
                    if time.process_time() - t0 >= deadline:
                        break
                    sigma = math.exp(rng2.uniform(math.log(1e-5), math.log(1e-3)))
                    v = rng2.normal(0.0, 1.0, d)
                    nv = np.linalg.norm(v)
                    if nv > 0:
                        v = v / nv
                    z = z_best + Z @ (sigma * v)
                    arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
                    arr[:, 2] = np.maximum(arr[:, 2], 1e-6)
                    arr[:, 0] = np.clip(arr[:, 0], arr[:, 2], 1.0 - arr[:, 2])
                    arr[:, 1] = np.clip(arr[:, 1], arr[:, 2], 1.0 - arr[:, 2])
                    arr = _exact_clean(arr)
                    try:
                        z0 = _to_z(arr)
                        zz = _run_slsqp(z0, cons_ineq, 2000, 1e-14)
                        arr2 = np.column_stack([zz[0::3], zz[1::3], zz[2::3]])
                        arr2 = _exact_clean(arr2)
                        if not _check_zero_tol(arr2):
                            continue
                        sc = float(np.sum(arr2[:, 2]))
                        if sc > best_score:
                            best = arr2
                            best_score = sc
                            z_best = _to_z(best)
                    except Exception:
                        continue
        except Exception:
            pass

    best = _exact_clean(best)
    if not _check_zero_tol(best):
        best[:, 2] = np.maximum(best[:, 2] - 1e-7, 1e-9)
        best[:, 0] = np.clip(best[:, 0], best[:, 2], 1.0 - best[:, 2])
        best[:, 1] = np.clip(best[:, 1], best[:, 2], 1.0 - best[:, 2])
        best = _exact_clean(best)
    return best

import numpy as np
import time
import math
from scipy.optimize import minimize

N = 26


def _unpack(z):
    return z[0::3], z[1::3], z[2::3]


def _neg_sum(z):
    return -np.sum(z[2::3])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g[2::3] = -1.0
    return g


def _neg_logsum(z):
    r = z[2::3]
    r = np.maximum(r, 1e-12)
    return -np.sum(np.log(r))


def _neg_logsum_grad(z):
    g = np.zeros_like(z)
    r = np.maximum(z[2::3], 1e-12)
    g[2::3] = -1.0 / r
    return g


def _make_constraints():
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def wall(z):
        x, y, r = _unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * N, 3 * N))
        for i in range(N):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[N + i, 3 * i] = -1.0; J[N + i, 3 * i + 2] = -1.0
            J[2 * N + i, 3 * i + 1] = 1.0; J[2 * N + i, 3 * i + 2] = -1.0
            J[3 * N + i, 3 * i + 1] = -1.0; J[3 * N + i, 3 * i + 2] = -1.0
        return J

    def pair(z):
        x, y, r = _unpack(z)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    def pair_jac(z):
        x, y, r = _unpack(z)
        J = np.zeros((len(pairs), 3 * N))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (r[i] + r[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
        return J

    return [
        {'type': 'ineq', 'fun': wall, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair, 'jac': pair_jac},
    ]


def _feasible(x, y, r, tol=1e-7):
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _run_slsqp(z0, cons, maxiter, ftol, fun=_neg_sum, jac=_neg_sum_grad):
    try:
        res = minimize(fun, z0, jac=jac, method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x
    except Exception:
        return z0


def _clean(z):
    x, y, r = _unpack(z)
    r = np.maximum(r, 0.0)
    r = r - 1e-9
    r = np.maximum(r, 1e-9)
    x = np.clip(x, r, 1 - r)
    y = np.clip(y, r, 1 - r)
    return np.column_stack([x, y, r])


def _to_z(arr):
    z = np.empty(3 * N)
    z[0::3] = arr[:, 0]
    z[1::3] = arr[:, 1]
    z[2::3] = arr[:, 2]
    return z


def _nextafter_down_slack_pass(arr):
    x = arr[:, 0].copy()
    y = arr[:, 1].copy()
    r = arr[:, 2].copy()
    for _ in range(12):
        m = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))
        for i in range(N):
            dx = x[i] - x
            dy = y[i] - y
            d = np.sqrt(dx * dx + dy * dy) - r
            d[i] = np.inf
            mi = np.min(d)
            if mi < m[i]:
                m[i] = mi
        r = np.minimum(r, m)
        r = np.nextafter(r, -np.inf)
        r = np.maximum(r, 1e-12)
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _check_zero_tol(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < 0) or np.any(x + r > 1):
        return False
    if np.any(y - r < 0) or np.any(y + r > 1):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                return False
    return True


def _violating_indices(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    bad = set()
    for i in range(N):
        if r[i] <= 0 or x[i] - r[i] < 0 or x[i] + r[i] > 1 \
                or y[i] - r[i] < 0 or y[i] + r[i] > 1:
            bad.add(i)
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                bad.add(i); bad.add(j)
    return bad


def _repair(arr):
    result = _nextafter_down_slack_pass(arr)
    tries = 0
    while not _check_zero_tol(result) and tries < 30:
        bad = _violating_indices(result)
        if not bad:
            break
        for i in bad:
            result[i, 2] = np.nextafter(result[i, 2], -np.inf)
        result[:, 2] = np.maximum(result[:, 2], 1e-12)
        result = _nextafter_down_slack_pass(result)
        tries += 1
    return result


def _make_corner_seeds():
    """Four-corner-dominant seeds: 4 large corner circles + 22 small ones via FPS."""
    seeds = []
    for Rc in (0.09, 0.10, 0.11, 0.12):
        for margin in (0.00, 0.01, 0.02):
            corners = [
                (Rc + margin, Rc + margin),
                (1 - Rc - margin, Rc + margin),
                (Rc + margin, 1 - Rc - margin),
                (1 - Rc - margin, 1 - Rc - margin),
            ]
            pts = [(cx, cy, Rc) for (cx, cy) in corners]
            # farthest-point sampling for 22 small circles
            cand = []
            g = 15
            for i in range(g):
                for j in range(g):
                    px = 0.02 + (0.96) * i / (g - 1)
                    py = 0.02 + (0.96) * j / (g - 1)
                    ok = True
                    for (cx, cy) in corners:
                        if (px - cx) ** 2 + (py - cy) ** 2 < (Rc + 0.02) ** 2:
                            ok = False
                            break
                    if ok:
                        cand.append((px, py))
            if len(cand) < 22:
                # fallback grid
                cand = []
                for i in range(g):
                    for j in range(g):
                        px = 0.02 + 0.96 * i / (g - 1)
                        py = 0.02 + 0.96 * j / (g - 1)
                        cand.append((px, py))
            chosen = []
            # start from a point far from corners
            best_p = max(cand, key=lambda p: min((p[0] - cx) ** 2 + (p[1] - cy) ** 2
                                                  for (cx, cy) in corners))
            chosen.append(best_p)
            while len(chosen) < 22:
                best_p = None
                best_d = -1.0
                for p in cand:
                    if p in chosen:
                        continue
                    d = min((p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2 for q in chosen)
                    if d > best_d:
                        best_d = d
                        best_p = p
                if best_p is None:
                    break
                chosen.append(best_p)
            for (px, py) in chosen[:22]:
                pts.append((px, py, 0.04))
            while len(pts) < N:
                pts.append((0.5, 0.5, 0.03))
            seeds.append(np.array(pts[:N]))
    return seeds


def construct(budget_seconds, start):
    t0 = time.process_time()
    seeds = _make_corner_seeds()
    cons = _make_constraints()

    best_out = None
    best_score = -np.inf

    # include start as a candidate baseline
    if start is not None:
        try:
            s = np.array(start, dtype=float)
            if s.shape == (N, 3):
                sc = np.sum(s[:, 2])
                if _feasible(s[:, 0], s[:, 1], s[:, 2]):
                    best_out = s.copy()
                    best_score = sc
        except Exception:
            pass

    for si, base in enumerate(seeds):
        if time.process_time() - t0 > budget_seconds * 0.75:
            break
        base = base.copy()
        base[:, 2] = np.maximum(base[:, 2], 1e-4)
        base[:, 0] = np.clip(base[:, 0], base[:, 2], 1 - base[:, 2])
        base[:, 1] = np.clip(base[:, 1], base[:, 2], 1 - base[:, 2])
        z0 = _to_z(base)

        z_log = _run_slsqp(z0, cons, 800, 1e-12,
                           fun=_neg_logsum, jac=_neg_logsum_grad)
        arr_log = _clean(z_log)

        z_sum = _run_slsqp(_to_z(arr_log), cons, 1200, 1e-10)
        out = _clean(z_sum)
        if _feasible(out[:, 0], out[:, 1], out[:, 2]):
            sc = np.sum(out[:, 2])
            if sc > best_score:
                best_score = sc
                best_out = out

        z_direct = _run_slsqp(z0, cons, 1200, 1e-10)
        out_d = _clean(z_direct)
        if _feasible(out_d[:, 0], out_d[:, 1], out_d[:, 2]):
            sc = np.sum(out_d[:, 2])
            if sc > best_score:
                best_score = sc
                best_out = out_d

    if best_out is None:
        k = int(np.ceil(np.sqrt(N)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
        best_out = np.array([[x, y, 0.02] for x, y in pts])

    if time.process_time() - t0 < budget_seconds * 0.90:
        z_final = _run_slsqp(_to_z(best_out), cons, 800, 1e-14)
        arr_c = _clean(z_final)
        if _feasible(arr_c[:, 0], arr_c[:, 1], arr_c[:, 2]):
            if np.sum(arr_c[:, 2]) >= best_score:
                best_out = arr_c

    result = _repair(best_out)
    return result

import numpy as np
import time
import math
from scipy.optimize import minimize

N = 26


def _unpack(z):
    return z[0::3], z[1::3], z[2::3]


def _neg_sum(z):
    return -np.sum(z[2::3])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g[2::3] = -1.0
    return g


def _make_constraints(active_pairs=None, active_walls=None):
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def wall(z):
        x, y, r = _unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * N, 3 * N))
        for i in range(N):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[N + i, 3 * i] = -1.0; J[N + i, 3 * i + 2] = -1.0
            J[2 * N + i, 3 * i + 1] = 1.0; J[2 * N + i, 3 * i + 2] = -1.0
            J[3 * N + i, 3 * i + 1] = -1.0; J[3 * N + i, 3 * i + 2] = -1.0
        return J

    def pair(z):
        x, y, r = _unpack(z)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    def pair_jac(z):
        x, y, r = _unpack(z)
        J = np.zeros((len(pairs), 3 * N))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (r[i] + r[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
        return J

    cons = [
        {'type': 'ineq', 'fun': wall, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair, 'jac': pair_jac},
    ]

    if active_pairs:
        def apair(z):
            x, y, r = _unpack(z)
            out = np.empty(len(active_pairs))
            for k, (i, j) in enumerate(active_pairs):
                dx = x[i] - x[j]; dy = y[i] - y[j]
                out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
            return out

        def apair_jac(z):
            x, y, r = _unpack(z)
            J = np.zeros((len(active_pairs), 3 * N))
            for k, (i, j) in enumerate(active_pairs):
                dx = x[i] - x[j]; dy = y[i] - y[j]
                J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
                J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
                s = -2 * (r[i] + r[j])
                J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
            return J

        cons.append({'type': 'eq', 'fun': apair, 'jac': apair_jac})

    if active_walls:
        def awall(z):
            x, y, r = _unpack(z)
            out = np.empty(len(active_walls))
            for k, (i, kind) in enumerate(active_walls):
                if kind == 0:
                    out[k] = x[i] - r[i]
                elif kind == 1:
                    out[k] = 1.0 - x[i] - r[i]
                elif kind == 2:
                    out[k] = y[i] - r[i]
                else:
                    out[k] = 1.0 - y[i] - r[i]
            return out

        def awall_jac(z):
            J = np.zeros((len(active_walls), 3 * N))
            for k, (i, kind) in enumerate(active_walls):
                if kind == 0:
                    J[k, 3 * i] = 1.0; J[k, 3 * i + 2] = -1.0
                elif kind == 1:
                    J[k, 3 * i] = -1.0; J[k, 3 * i + 2] = -1.0
                elif kind == 2:
                    J[k, 3 * i + 1] = 1.0; J[k, 3 * i + 2] = -1.0
                else:
                    J[k, 3 * i + 1] = -1.0; J[k, 3 * i + 2] = -1.0
            return J

        cons.append({'type': 'eq', 'fun': awall, 'jac': awall_jac})

    return cons


def _run_slsqp(z0, cons, maxiter, ftol):
    try:
        res = minimize(_neg_sum, z0, jac=_neg_sum_grad, method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x
    except Exception:
        return z0


def _to_z(arr):
    z = np.empty(3 * N)
    z[0::3] = arr[:, 0]
    z[1::3] = arr[:, 1]
    z[2::3] = arr[:, 2]
    return z


def _exact_clean(arr):
    x = arr[:, 0].copy()
    y = arr[:, 1].copy()
    r = arr[:, 2].copy()
    r = np.maximum(r, 1e-9)
    for _ in range(8):
        m = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))
        for i in range(N):
            dx = x[i] - x
            dy = y[i] - y
            d = np.sqrt(dx * dx + dy * dy) - r
            d[i] = np.inf
            mi = np.min(d)
            if mi < m[i]:
                m[i] = mi
        r = np.minimum(r, m)
        r = np.nextafter(r, -np.inf)
        r = np.maximum(r, 1e-12)
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _check_zero_tol(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < 0) or np.any(x + r > 1):
        return False
    if np.any(y - r < 0) or np.any(y + r > 1):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                return False
    return True


def _feasible_loose(arr, tol=1e-7):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _fallback():
    k = int(np.ceil(np.sqrt(N)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
    return np.array([[x, y, 0.02] for x, y in pts])


def _find_active(arr, tol=1e-9):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    active_pairs = []
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = math.sqrt(dx * dx + dy * dy)
            gap = d - (r[i] + r[j])
            if gap < tol:
                active_pairs.append((i, j))
    active_walls = []
    for i in range(N):
        if x[i] - r[i] < tol:
            active_walls.append((i, 0))
        if 1.0 - x[i] - r[i] < tol:
            active_walls.append((i, 1))
        if y[i] - r[i] < tol:
            active_walls.append((i, 2))
        if 1.0 - y[i] - r[i] < tol:
            active_walls.append((i, 3))
    return active_pairs, active_walls


def _polish(arr, t0, deadline):
    """Run Phase 1 (equality) then Phase 2 (inequality) polish. Return cleaned arr."""
    best = arr
    # Phase 1
    try:
        ap, aw = _find_active(best, tol=1e-9)
        cons_eq = _make_constraints(ap, aw)
        z0 = _to_z(best)
        z = _run_slsqp(z0, cons_eq, 3000, 1e-14)
        a = np.column_stack([z[0::3], z[1::3], z[2::3]])
        a = _exact_clean(a)
        if _check_zero_tol(a):
            if float(np.sum(a[:, 2])) > float(np.sum(best[:, 2])):
                best = a
    except Exception:
        pass
    # Phase 2
    if time.process_time() - t0 < deadline:
        try:
            cons = _make_constraints()
            z0 = _to_z(best)
            z = _run_slsqp(z0, cons, 3000, 1e-14)
            a = np.column_stack([z[0::3], z[1::3], z[2::3]])
            a = _exact_clean(a)
            if _check_zero_tol(a):
                if float(np.sum(a[:, 2])) > float(np.sum(best[:, 2])):
                    best = a
        except Exception:
            pass
    return best


def _best_insert_point(x, y, r, others_mask, r_new):
    """Find point (px,py) maximizing min(wall clearance, min_j(d - r_j)) vs others."""
    ox = x[others_mask]
    oy = y[others_mask]
    orr = r[others_mask]
    # grid
    g = np.linspace(0.01, 0.99, 50)
    GX, GY = np.meshgrid(g, g)
    px = GX.ravel()
    py = GY.ravel()
    # random
    rng = np.random.default_rng(9876)
    rx = rng.uniform(0.01, 0.99, 5000)
    ry = rng.uniform(0.01, 0.99, 5000)
    px = np.concatenate([px, rx])
    py = np.concatenate([py, ry])
    # wall clearance
    wc = np.minimum(np.minimum(px, 1.0 - px), np.minimum(py, 1.0 - py))
    # pair clearance
    if len(ox) > 0:
        dx = px[:, None] - ox[None, :]
        dy = py[:, None] - oy[None, :]
        d = np.sqrt(dx * dx + dy * dy) - orr[None, :]
        pc = np.min(d, axis=1)
    else:
        pc = np.full(len(px), np.inf)
    score = np.minimum(wc, pc)
    k = int(np.argmax(score))
    return float(px[k]), float(py[k])


def construct(budget_seconds, start):
    t0 = time.process_time()

    best = None
    best_score = -np.inf

    if start is not None:
        s = np.array(start, dtype=float)
        if s.shape == (N, 3) and _feasible_loose(s):
            s = _exact_clean(s)
            if _check_zero_tol(s):
                best = s
                best_score = float(np.sum(s[:, 2]))

    if best is None:
        best = _exact_clean(_fallback())
        best_score = float(np.sum(best[:, 2]))

    deadline = budget_seconds * 0.85

    # Baseline polish (same as base program Phase 1+2)
    polished = _polish(best, t0, deadline)
    if _check_zero_tol(polished):
        sc = float(np.sum(polished[:, 2]))
        if sc > best_score:
            best = polished
            best_score = sc

    # Experiment: find two smallest-radius circles whose centers are within 0.02
    x = best[:, 0].copy()
    y = best[:, 1].copy()
    r = best[:, 2].copy()
    order = np.argsort(r)
    pair = None
    for a_idx in range(len(order)):
        i = order[a_idx]
        for b_idx in range(a_idx + 1, len(order)):
            j = order[b_idx]
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy <= 0.02 * 0.02:
                pair = (int(i), int(j))
                break
        if pair is not None:
            break

    if pair is not None and time.process_time() - t0 < deadline:
        i, j = pair
        r_new = 1e-4
        cand = best.copy()
        cand[i, 2] = r_new
        cand[j, 2] = r_new
        # place i first against other 25
        mask = np.ones(N, dtype=bool)
        mask[i] = False
        px, py = _best_insert_point(cand[:, 0], cand[:, 1], cand[:, 2], mask, r_new)
        cand[i, 0] = px; cand[i, 1] = py
        # then j against other 25 (including new i)
        mask = np.ones(N, dtype=bool)
        mask[j] = False
        px, py = _best_insert_point(cand[:, 0], cand[:, 1], cand[:, 2], mask, r_new)
        cand[j, 0] = px; cand[j, 1] = py
        # clip to walls
        cand[:, 0] = np.clip(cand[:, 0], cand[:, 2], 1.0 - cand[:, 2])
        cand[:, 1] = np.clip(cand[:, 1], cand[:, 2], 1.0 - cand[:, 2])
        cand = _exact_clean(cand)
        if _feasible_loose(cand, tol=1e-5):
            polished = _polish(cand, t0, deadline)
            if _check_zero_tol(polished):
                sc = float(np.sum(polished[:, 2]))
                if sc > best_score + 1e-12:
                    best = polished
                    best_score = sc

    best = _exact_clean(best)
    if not _check_zero_tol(best):
        best[:, 2] = np.maximum(best[:, 2] - 1e-7, 1e-9)
        best[:, 0] = np.clip(best[:, 0], best[:, 2], 1.0 - best[:, 2])
        best[:, 1] = np.clip(best[:, 1], best[:, 2], 1.0 - best[:, 2])
        best = _exact_clean(best)
    return best

import numpy as np
import time
import math
from scipy.optimize import minimize, linprog

N = 26


def _unpack(z):
    return z[0::3], z[1::3], z[2::3]


def _neg_sum(z):
    return -np.sum(z[2::3])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g[2::3] = -1.0
    return g


def _make_constraints(active_pairs=None, active_walls=None):
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def wall(z):
        x, y, r = _unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * N, 3 * N))
        for i in range(N):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[N + i, 3 * i] = -1.0; J[N + i, 3 * i + 2] = -1.0
            J[2 * N + i, 3 * i + 1] = 1.0; J[2 * N + i, 3 * i + 2] = -1.0
            J[3 * N + i, 3 * i + 1] = -1.0; J[3 * N + i, 3 * i + 2] = -1.0
        return J

    def pair(z):
        x, y, r = _unpack(z)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    def pair_jac(z):
        x, y, r = _unpack(z)
        J = np.zeros((len(pairs), 3 * N))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (r[i] + r[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
        return J

    cons = [
        {'type': 'ineq', 'fun': wall, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair, 'jac': pair_jac},
    ]

    if active_pairs:
        def apair(z):
            x, y, r = _unpack(z)
            out = np.empty(len(active_pairs))
            for k, (i, j) in enumerate(active_pairs):
                dx = x[i] - x[j]; dy = y[i] - y[j]
                out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
            return out

        def apair_jac(z):
            x, y, r = _unpack(z)
            J = np.zeros((len(active_pairs), 3 * N))
            for k, (i, j) in enumerate(active_pairs):
                dx = x[i] - x[j]; dy = y[i] - y[j]
                J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
                J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
                s = -2 * (r[i] + r[j])
                J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
            return J

        cons.append({'type': 'eq', 'fun': apair, 'jac': apair_jac})

    if active_walls:
        def awall(z):
            x, y, r = _unpack(z)
            out = np.empty(len(active_walls))
            for k, (i, kind) in enumerate(active_walls):
                if kind == 0:
                    out[k] = x[i] - r[i]
                elif kind == 1:
                    out[k] = 1.0 - x[i] - r[i]
                elif kind == 2:
                    out[k] = y[i] - r[i]
                else:
                    out[k] = 1.0 - y[i] - r[i]
            return out

        def awall_jac(z):
            J = np.zeros((len(active_walls), 3 * N))
            for k, (i, kind) in enumerate(active_walls):
                if kind == 0:
                    J[k, 3 * i] = 1.0; J[k, 3 * i + 2] = -1.0
                elif kind == 1:
                    J[k, 3 * i] = -1.0; J[k, 3 * i + 2] = -1.0
                elif kind == 2:
                    J[k, 3 * i + 1] = 1.0; J[k, 3 * i + 2] = -1.0
                else:
                    J[k, 3 * i + 1] = -1.0; J[k, 3 * i + 2] = -1.0
            return J

        cons.append({'type': 'eq', 'fun': awall, 'jac': awall_jac})

    return cons


def _run_slsqp(z0, cons, maxiter, ftol):
    try:
        res = minimize(_neg_sum, z0, jac=_neg_sum_grad, method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x
    except Exception:
        return z0


def _to_z(arr):
    z = np.empty(3 * N)
    z[0::3] = arr[:, 0]
    z[1::3] = arr[:, 1]
    z[2::3] = arr[:, 2]
    return z


def _exact_clean(arr):
    x = arr[:, 0].copy()
    y = arr[:, 1].copy()
    r = arr[:, 2].copy()
    r = np.maximum(r, 1e-9)
    for _ in range(8):
        m = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))
        for i in range(N):
            dx = x[i] - x
            dy = y[i] - y
            d = np.sqrt(dx * dx + dy * dy) - r
            d[i] = np.inf
            mi = np.min(d)
            if mi < m[i]:
                m[i] = mi
        r = np.minimum(r, m)
        r = np.nextafter(r, -np.inf)
        r = np.maximum(r, 1e-12)
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _check_zero_tol(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < 0) or np.any(x + r > 1):
        return False
    if np.any(y - r < 0) or np.any(y + r > 1):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                return False
    return True


def _feasible_loose(arr, tol=1e-7):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _fallback():
    k = int(np.ceil(np.sqrt(N)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
    return np.array([[x, y, 0.02] for x, y in pts])


def _find_active(arr, tol=1e-9):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    active_pairs = []
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = math.sqrt(dx * dx + dy * dy)
            gap = d - (r[i] + r[j])
            if gap < tol:
                active_pairs.append((i, j))
    active_walls = []
    for i in range(N):
        if x[i] - r[i] < tol:
            active_walls.append((i, 0))
        if 1.0 - x[i] - r[i] < tol:
            active_walls.append((i, 1))
        if y[i] - r[i] < tol:
            active_walls.append((i, 2))
        if 1.0 - y[i] - r[i] < tol:
            active_walls.append((i, 3))
    return active_pairs, active_walls


def _lp_eval(centers):
    """Solve LP maximizing sum(r) for fixed centers. Return (sum, radii) or (None, None)."""
    x = centers[:, 0]
    y = centers[:, 1]
    eps = 1e-12
    # Variables: r_0..r_{N-1}, maximize sum -> minimize -sum
    c = -np.ones(N)
    A_ub = []
    b_ub = []
    # Wall constraints: r_i <= x_i - eps, r_i <= 1-x_i - eps, etc.
    for i in range(N):
        row = np.zeros(N); row[i] = 1.0
        A_ub.append(row.copy()); b_ub.append(x[i] - eps)
        A_ub.append(row.copy()); b_ub.append(1.0 - x[i] - eps)
        A_ub.append(row.copy()); b_ub.append(y[i] - eps)
        A_ub.append(row.copy()); b_ub.append(1.0 - y[i] - eps)
    # Pair constraints: r_i + r_j <= dist - eps
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = math.hypot(dx, dy)
            row = np.zeros(N); row[i] = 1.0; row[j] = 1.0
            A_ub.append(row); b_ub.append(d - eps)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=[(0, None)] * N, method='highs')
        if res.success:
            return -res.fun, res.x
    except Exception:
        pass
    return None, None


def construct(budget_seconds, start):
    t0 = time.process_time()

    best = None
    best_score = -np.inf

    if start is not None:
        s = np.array(start, dtype=float)
        if s.shape == (N, 3) and _feasible_loose(s):
            s = _exact_clean(s)
            if _check_zero_tol(s):
                best = s
                best_score = float(np.sum(s[:, 2]))

    if best is None:
        best = _exact_clean(_fallback())
        best_score = float(np.sum(best[:, 2]))

    deadline = budget_seconds * 0.85

    # Phase 1: equality-constrained polish of the start's contact graph
    try:
        ap, aw = _find_active(best, tol=1e-9)
        cons_eq = _make_constraints(ap, aw)
        z0 = _to_z(best)
        z = _run_slsqp(z0, cons_eq, 3000, 1e-14)
        arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
        arr = _exact_clean(arr)
        if _check_zero_tol(arr):
            sc = float(np.sum(arr[:, 2]))
            if sc > best_score:
                best = arr
                best_score = sc
    except Exception:
        pass

    # Phase 2: inequality-only SLSQP polish
    if time.process_time() - t0 < deadline:
        try:
            cons = _make_constraints()
            z0 = _to_z(best)
            z = _run_slsqp(z0, cons, 3000, 1e-14)
            arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
            arr = _exact_clean(arr)
            if _check_zero_tol(arr):
                sc = float(np.sum(arr[:, 2]))
                if sc > best_score:
                    best = arr
                    best_score = sc
        except Exception:
            pass

    # Phase 3: small random restarts with equality constraints on current active set
    rng = np.random.default_rng(12345)
    while time.process_time() - t0 < deadline:
        try:
            ap, aw = _find_active(best, tol=1e-9)
            cons_eq = _make_constraints(ap, aw)
            sigma = math.exp(rng.uniform(math.log(1e-4), math.log(1e-2)))
            cand = best.copy()
            cand[:, 0] += rng.normal(0.0, sigma, N)
            cand[:, 1] += rng.normal(0.0, sigma, N)
            cand[:, 2] += rng.normal(0.0, 0.5 * sigma, N)
            cand[:, 2] = np.maximum(cand[:, 2], 1e-6)
            cand[:, 0] = np.clip(cand[:, 0], cand[:, 2], 1.0 - cand[:, 2])
            cand[:, 1] = np.clip(cand[:, 1], cand[:, 2], 1.0 - cand[:, 2])
            z0 = _to_z(cand)
            z = _run_slsqp(z0, cons_eq, 3000, 1e-14)
            arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
            arr = _exact_clean(arr)
            if not _check_zero_tol(arr):
                continue
            sc = float(np.sum(arr[:, 2]))
            if sc > best_score:
                best = arr
                best_score = sc
        except Exception:
            continue

    # Phase 4: dual-LP subgradient ascent on centers
    lp_deadline = budget_seconds * 0.97
    try:
        centers = best[:, :2].copy()
        cur_sum, cur_r = _lp_eval(centers)
        if cur_sum is not None:
            step_sizes = [1e-3, 5e-4, 2e-4, 1e-4, 5e-5]
            h = 1e-5
            for it in range(200):
                if time.process_time() - t0 > lp_deadline:
                    break
                # central differences gradient
                grad = np.zeros((N, 2))
                for i in range(N):
                    for d in range(2):
                        cp = centers.copy(); cp[i, d] += h
                        cm = centers.copy(); cm[i, d] -= h
                        sp, _ = _lp_eval(cp)
                        sm, _ = _lp_eval(cm)
                        if sp is None or sm is None:
                            grad[i, d] = 0.0
                        else:
                            grad[i, d] = (sp - sm) / (2 * h)
                gn = np.linalg.norm(grad)
                if gn < 1e-12:
                    break
                gdir = grad / gn
                improved = False
                for step in step_sizes:
                    cand_c = centers + step * gdir
                    # clip using current LP radii
                    if cur_r is not None:
                        rr = np.maximum(cur_r, 1e-9)
                    else:
                        rr = np.full(N, 1e-6)
                    cand_c[:, 0] = np.clip(cand_c[:, 0], rr, 1.0 - rr)
                    cand_c[:, 1] = np.clip(cand_c[:, 1], rr, 1.0 - rr)
                    s_new, r_new = _lp_eval(cand_c)
                    if s_new is not None and s_new > cur_sum + 1e-12:
                        centers = cand_c
                        cur_sum = s_new
                        cur_r = r_new
                        improved = True
                        break
                if not improved:
                    break
            # Build candidate from LP solution and run SLSQP
            if cur_r is not None and cur_sum is not None and cur_sum > best_score + 1e-9:
                cand = np.column_stack([centers[:, 0], centers[:, 1], cur_r])
                cand = _exact_clean(cand)
                if _check_zero_tol(cand):
                    try:
                        cons = _make_constraints()
                        z0 = _to_z(cand)
                        z = _run_slsqp(z0, cons, 3000, 1e-14)
                        arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
                        arr = _exact_clean(arr)
                        if _check_zero_tol(arr):
                            sc = float(np.sum(arr[:, 2]))
                            if sc > best_score:
                                best = arr
                                best_score = sc
                    except Exception:
                        pass
    except Exception:
        pass

    best = _exact_clean(best)
    if not _check_zero_tol(best):
        best[:, 2] = np.maximum(best[:, 2] - 1e-7, 1e-9)
        best[:, 0] = np.clip(best[:, 0], best[:, 2], 1.0 - best[:, 2])
        best[:, 1] = np.clip(best[:, 1], best[:, 2], 1.0 - best[:, 2])
        best = _exact_clean(best)
    return best

import numpy as np
import time
import math
from scipy.optimize import minimize

N = 26


def _unpack(z):
    return z[0::3], z[1::3], z[2::3]


def _neg_sum(z):
    return -np.sum(z[2::3])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g[2::3] = -1.0
    return g


def _neg_logsum(z):
    r = z[2::3]
    r = np.maximum(r, 1e-12)
    return -np.sum(np.log(r))


def _neg_logsum_grad(z):
    g = np.zeros_like(z)
    r = np.maximum(z[2::3], 1e-12)
    g[2::3] = -1.0 / r
    return g


def _make_constraints():
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def wall(z):
        x, y, r = _unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * N, 3 * N))
        for i in range(N):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[N + i, 3 * i] = -1.0; J[N + i, 3 * i + 2] = -1.0
            J[2 * N + i, 3 * i + 1] = 1.0; J[2 * N + i, 3 * i + 2] = -1.0
            J[3 * N + i, 3 * i + 1] = -1.0; J[3 * N + i, 3 * i + 2] = -1.0
        return J

    def pair(z):
        x, y, r = _unpack(z)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    def pair_jac(z):
        x, y, r = _unpack(z)
        J = np.zeros((len(pairs), 3 * N))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (r[i] + r[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
        return J

    return [
        {'type': 'ineq', 'fun': wall, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair, 'jac': pair_jac},
    ]


def _feasible(x, y, r, tol=1e-7):
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _run_slsqp(z0, cons, maxiter, ftol, fun=_neg_sum, jac=_neg_sum_grad):
    try:
        res = minimize(fun, z0, jac=jac, method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x
    except Exception:
        return z0


def _clean(z):
    x, y, r = _unpack(z)
    r = np.maximum(r, 0.0)
    r = r - 1e-9
    r = np.maximum(r, 1e-9)
    x = np.clip(x, r, 1 - r)
    y = np.clip(y, r, 1 - r)
    return np.column_stack([x, y, r])


def _to_z(arr):
    z = np.empty(3 * N)
    z[0::3] = arr[:, 0]
    z[1::3] = arr[:, 1]
    z[2::3] = arr[:, 2]
    return z


def _nextafter_down_slack_pass(arr):
    x = arr[:, 0].copy()
    y = arr[:, 1].copy()
    r = arr[:, 2].copy()
    for _ in range(12):
        m = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))
        for i in range(N):
            dx = x[i] - x
            dy = y[i] - y
            d = np.sqrt(dx * dx + dy * dy) - r
            d[i] = np.inf
            mi = np.min(d)
            if mi < m[i]:
                m[i] = mi
        r = np.minimum(r, m)
        r = np.nextafter(r, -np.inf)
        r = np.maximum(r, 1e-12)
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _check_zero_tol(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < 0) or np.any(x + r > 1):
        return False
    if np.any(y - r < 0) or np.any(y + r > 1):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                return False
    return True


def _violating_indices(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    bad = set()
    for i in range(N):
        if r[i] <= 0 or x[i] - r[i] < 0 or x[i] + r[i] > 1 \
                or y[i] - r[i] < 0 or y[i] + r[i] > 1:
            bad.add(i)
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                bad.add(i); bad.add(j)
    return bad


def _repair(arr):
    result = _nextafter_down_slack_pass(arr)
    tries = 0
    while not _check_zero_tol(result) and tries < 30:
        bad = _violating_indices(result)
        if not bad:
            break
        for i in bad:
            result[i, 2] = np.nextafter(result[i, 2], -np.inf)
        result[:, 2] = np.maximum(result[:, 2], 1e-12)
        result = _nextafter_down_slack_pass(result)
        tries += 1
    return result


def _make_central_seeds():
    """Seeds: one large central circle + 25 small satellites on rings."""
    seeds = []
    for Rc in (0.16, 0.18, 0.20):
        for rsmall in (0.025, 0.032, 0.040):
            for inner_frac in (0.35, 0.45, 0.55):
                pts = [(0.5, 0.5, Rc)]
                n_in = 10
                r_in = inner_frac
                for k in range(n_in):
                    a = 2 * math.pi * k / n_in
                    pts.append((0.5 + r_in * math.cos(a),
                                0.5 + r_in * math.sin(a), rsmall))
                n_out = 15
                r_out = 0.5 - rsmall - 0.01
                for k in range(n_out):
                    a = 2 * math.pi * k / n_out + math.pi / n_out
                    pts.append((0.5 + r_out * math.cos(a),
                                0.5 + r_out * math.sin(a), rsmall))
                seeds.append(np.array(pts[:N]))
    for Rc in (0.16, 0.18, 0.20):
        for rsmall in (0.025, 0.032, 0.040):
            pts = [(0.5, 0.5, Rc)]
            d1 = 0.5 - rsmall - 0.01
            for k in range(6):
                a = math.pi / 3 * k
                pts.append((0.5 + d1 * math.cos(a), 0.5 + d1 * math.sin(a), rsmall))
            d2 = 0.5 - rsmall - 0.01
            for k in range(12):
                a = math.pi / 6 + math.pi / 6 * k
                pts.append((0.5 + d2 * math.cos(a), 0.5 + d2 * math.sin(a), rsmall))
            for k in range(6):
                a = math.pi / 3 * k + math.pi / 6
                pts.append((0.5 + 0.28 * math.cos(a), 0.5 + 0.28 * math.sin(a), rsmall))
            seeds.append(np.array(pts[:N]))
    return seeds


def _make_spiral_seeds():
    """Golden-angle spiral seeds: central circle + 25 satellites on a spiral."""
    seeds = []
    golden = 2.399963
    for Rc in (0.13, 0.14, 0.15):
        pts = [(0.5, 0.5, Rc)]
        for k in range(1, N):
            a = k * golden
            d = 0.45 * math.sqrt(k / (N - 1))
            x = 0.5 + d * math.cos(a)
            y = 0.5 + d * math.sin(a)
            pts.append((x, y, 0.035))
        seeds.append(np.array(pts[:N]))
    return seeds


def construct(budget_seconds, start):
    t0 = time.process_time()
    seeds = _make_spiral_seeds() + _make_central_seeds()
    cons = _make_constraints()

    best_out = None
    best_score = -np.inf

    # Consider start as a seed too
    if start is not None:
        try:
            s = np.array(start, dtype=float).reshape(N, 3).copy()
            s[:, 2] = np.maximum(s[:, 2], 1e-4)
            s[:, 0] = np.clip(s[:, 0], s[:, 2], 1 - s[:, 2])
            s[:, 1] = np.clip(s[:, 1], s[:, 2], 1 - s[:, 2])
            if _feasible(s[:, 0], s[:, 1], s[:, 2]):
                best_out = s.copy()
                best_score = float(np.sum(s[:, 2]))
        except Exception:
            pass

    for si, base in enumerate(seeds):
        if time.process_time() - t0 > budget_seconds * 0.75:
            break
        base = base.copy()
        base[:, 2] = np.maximum(base[:, 2], 1e-4)
        base[:, 0] = np.clip(base[:, 0], base[:, 2], 1 - base[:, 2])
        base[:, 1] = np.clip(base[:, 1], base[:, 2], 1 - base[:, 2])
        z0 = _to_z(base)

        z_log = _run_slsqp(z0, cons, 800, 1e-12,
                           fun=_neg_logsum, jac=_neg_logsum_grad)
        arr_log = _clean(z_log)

        z_sum = _run_slsqp(_to_z(arr_log), cons, 1200, 1e-10)
        out = _clean(z_sum)
        if _feasible(out[:, 0], out[:, 1], out[:, 2]):
            sc = np.sum(out[:, 2])
            if sc > best_score:
                best_score = sc
                best_out = out

        z_direct = _run_slsqp(z0, cons, 1200, 1e-10)
        out_d = _clean(z_direct)
        if _feasible(out_d[:, 0], out_d[:, 1], out_d[:, 2]):
            sc = np.sum(out_d[:, 2])
            if sc > best_score:
                best_score = sc
                best_out = out_d

    if best_out is None:
        k = int(np.ceil(np.sqrt(N)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
        best_out = np.array([[x, y, 0.02] for x, y in pts])

    if time.process_time() - t0 < budget_seconds * 0.90:
        z_final = _run_slsqp(_to_z(best_out), cons, 800, 1e-14)
        arr_c = _clean(z_final)
        if _feasible(arr_c[:, 0], arr_c[:, 1], arr_c[:, 2]):
            if np.sum(arr_c[:, 2]) >= best_score:
                best_out = arr_c

    result = _repair(best_out)
    return result

import numpy as np
import time
import math
from scipy.optimize import minimize

N = 26


def _unpack(z):
    return z[0::3], z[1::3], z[2::3]


def _neg_sum(z):
    return -np.sum(z[2::3])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g[2::3] = -1.0
    return g


def _make_constraints(active_pairs=None, active_walls=None):
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def wall(z):
        x, y, r = _unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * N, 3 * N))
        for i in range(N):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[N + i, 3 * i] = -1.0; J[N + i, 3 * i + 2] = -1.0
            J[2 * N + i, 3 * i + 1] = 1.0; J[2 * N + i, 3 * i + 2] = -1.0
            J[3 * N + i, 3 * i + 1] = -1.0; J[3 * N + i, 3 * i + 2] = -1.0
        return J

    def pair(z):
        x, y, r = _unpack(z)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    def pair_jac(z):
        x, y, r = _unpack(z)
        J = np.zeros((len(pairs), 3 * N))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (r[i] + r[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
        return J

    cons = [
        {'type': 'ineq', 'fun': wall, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair, 'jac': pair_jac},
    ]

    if active_pairs:
        def apair(z):
            x, y, r = _unpack(z)
            out = np.empty(len(active_pairs))
            for k, (i, j) in enumerate(active_pairs):
                dx = x[i] - x[j]; dy = y[i] - y[j]
                out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
            return out

        def apair_jac(z):
            x, y, r = _unpack(z)
            J = np.zeros((len(active_pairs), 3 * N))
            for k, (i, j) in enumerate(active_pairs):
                dx = x[i] - x[j]; dy = y[i] - y[j]
                J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
                J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
                s = -2 * (r[i] + r[j])
                J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
            return J

        cons.append({'type': 'eq', 'fun': apair, 'jac': apair_jac})

    if active_walls:
        def awall(z):
            x, y, r = _unpack(z)
            out = np.empty(len(active_walls))
            for k, (i, kind) in enumerate(active_walls):
                if kind == 0:
                    out[k] = x[i] - r[i]
                elif kind == 1:
                    out[k] = 1.0 - x[i] - r[i]
                elif kind == 2:
                    out[k] = y[i] - r[i]
                else:
                    out[k] = 1.0 - y[i] - r[i]
            return out

        def awall_jac(z):
            J = np.zeros((len(active_walls), 3 * N))
            for k, (i, kind) in enumerate(active_walls):
                if kind == 0:
                    J[k, 3 * i] = 1.0; J[k, 3 * i + 2] = -1.0
                elif kind == 1:
                    J[k, 3 * i] = -1.0; J[k, 3 * i + 2] = -1.0
                elif kind == 2:
                    J[k, 3 * i + 1] = 1.0; J[k, 3 * i + 2] = -1.0
                else:
                    J[k, 3 * i + 1] = -1.0; J[k, 3 * i + 2] = -1.0
        return J

    return cons


def _run_slsqp(z0, cons, maxiter, ftol):
    try:
        res = minimize(_neg_sum, z0, jac=_neg_sum_grad, method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x
    except Exception:
        return z0


def _to_z(arr):
    z = np.empty(3 * N)
    z[0::3] = arr[:, 0]
    z[1::3] = arr[:, 1]
    z[2::3] = arr[:, 2]
    return z


def _exact_clean(arr):
    x = arr[:, 0].copy()
    y = arr[:, 1].copy()
    r = arr[:, 2].copy()
    r = np.maximum(r, 1e-9)
    for _ in range(8):
        m = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))
        for i in range(N):
            dx = x[i] - x
            dy = y[i] - y
            d = np.sqrt(dx * dx + dy * dy) - r
            d[i] = np.inf
            mi = np.min(d)
            if mi < m[i]:
                m[i] = mi
        r = np.minimum(r, m)
        r = np.nextafter(r, -np.inf)
        r = np.maximum(r, 1e-12)
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _check_zero_tol(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < 0) or np.any(x + r > 1):
        return False
    if np.any(y - r < 0) or np.any(y + r > 1):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                return False
    return True


def _feasible_loose(arr, tol=1e-7):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _fallback():
    k = int(np.ceil(np.sqrt(N)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
    return np.array([[x, y, 0.02] for x, y in pts])


def _find_active(arr, tol=1e-9):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    active_pairs = []
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = math.sqrt(dx * dx + dy * dy)
            gap = d - (r[i] + r[j])
            if gap < tol:
                active_pairs.append((i, j))
    active_walls = []
    for i in range(N):
        if x[i] - r[i] < tol:
            active_walls.append((i, 0))
        if 1.0 - x[i] - r[i] < tol:
            active_walls.append((i, 1))
        if y[i] - r[i] < tol:
            active_walls.append((i, 2))
        if 1.0 - y[i] - r[i] < tol:
            active_walls.append((i, 3))
    return active_pairs, active_walls


def _penalty(z):
    x, y, r = _unpack(z)
    pen = 0.0
    # walls
    v = np.concatenate([x - r, 1.0 - x - r, y - r, 1.0 - y - r])
    neg = np.minimum(v, 0.0)
    pen += np.sum(neg * neg)
    # pairs
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d2 = dx * dx + dy * dy
            s = r[i] + r[j]
            ov = s * s - d2
            if ov > 0:
                pen += ov * ov
    return -np.sum(r) + 1e7 * pen


def construct(budget_seconds, start):
    t0 = time.process_time()

    best = None
    best_score = -np.inf

    if start is not None:
        s = np.array(start, dtype=float)
        if s.shape == (N, 3) and _feasible_loose(s):
            s = _exact_clean(s)
            if _check_zero_tol(s):
                best = s
                best_score = float(np.sum(s[:, 2]))

    if best is None:
        best = _exact_clean(_fallback())
        best_score = float(np.sum(best[:, 2]))

    deadline = budget_seconds * 0.85

    # Experiment: Nelder-Mead on penalty objective from p0103 z
    if time.process_time() - t0 < deadline:
        try:
            z0 = _to_z(best)
            res = minimize(_penalty, z0, method='Nelder-Mead',
                           options={'maxiter': 20000, 'xatol': 1e-10,
                                    'fatol': 1e-10})
            z = res.x
            arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
            arr = _exact_clean(arr)
            # Then SLSQP inequality polish
            if time.process_time() - t0 < deadline:
                cons = _make_constraints()
                z2 = _run_slsqp(_to_z(arr), cons, 3000, 1e-14)
                arr2 = np.column_stack([z2[0::3], z2[1::3], z2[2::3]])
                arr2 = _exact_clean(arr2)
                if _check_zero_tol(arr2):
                    sc = float(np.sum(arr2[:, 2]))
                    if sc > best_score:
                        best = arr2
                        best_score = sc
            if _check_zero_tol(arr):
                sc = float(np.sum(arr[:, 2]))
                if sc > best_score:
                    best = arr
                    best_score = sc
        except Exception:
            pass

    best = _exact_clean(best)
    if not _check_zero_tol(best):
        best[:, 2] = np.maximum(best[:, 2] - 1e-7, 1e-9)
        best[:, 0] = np.clip(best[:, 0], best[:, 2], 1.0 - best[:, 2])
        best[:, 1] = np.clip(best[:, 1], best[:, 2], 1.0 - best[:, 2])
        best = _exact_clean(best)
    return best

