    r = arr[:, 2].copy()
    r = np.maximum(r, 1e-9)
    for _ in range(8):
        m = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))
        for i in range(N):
            dx = x[i] - x
            dy = y[i] - y
            d = np.sqrt(dx * dx + dy * dy) - r
            d[i] = np.inf
            mi = np.min(d)
            if mi < m[i]:
                m[i] = mi
        r = np.minimum(r, m)
        r = np.nextafter(r, -np.inf)
        r = np.maximum(r, 1e-12)
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _check_zero_tol(arr):
