        if y[i] - r[i] < tol:
            active_walls.append((i, 2))
        if 1.0 - y[i] - r[i] < tol:
            active_walls.append((i, 3))
    return active_pairs, active_walls


def _contact_counts(arr, tol=1e-9):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    cnt = np.zeros(N, dtype=int)
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = math.sqrt(dx * dx + dy * dy)
            if d - (r[i] + r[j]) < tol:
                cnt[i] += 1
                cnt[j] += 1
        if x[i] - r[i] < tol: cnt[i] += 1
        if 1.0 - x[i] - r[i] < tol: cnt[i] += 1
        if y[i] - r[i] < tol: cnt[i] += 1
        if 1.0 - y[i] - r[i] < tol: cnt[i] += 1
    return cnt


def construct(budget_seconds, start):
    t0 = time.process_time()

