    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _fallback():
    k = int(np.ceil(np.sqrt(N)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
    return np.array([[x, y, 0.02] for x, y in pts])


def _find_active(arr, tol=1e-9):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    active_pairs = []
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = math.sqrt(dx * dx + dy * dy)
            gap = d - (r[i] + r[j])
            if gap < tol:
                active_pairs.append((i, j))
    active_walls = []
    for i in range(N):
        if x[i] - r[i] < tol:
            active_walls.append((i, 0))
        if 1.0 - x[i] - r[i] < tol:
            active_walls.append((i, 1))
        if y[i] - r[i] < tol:
            active_walls.append((i, 2))
        if 1.0 - y[i] - r[i] < tol:
            active_walls.append((i, 3))
    return active_pairs, active_walls


def _clearances(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    c = np.empty(N)
    for i in range(N):
        w = min(x[i], 1.0 - x[i], y[i], 1.0 - y[i])
        dx = x[i] - x
        dy = y[i] - y
        d = np.sqrt(dx * dx + dy * dy) - r
        d[i] = np.inf
        c[i] = min(w, np.min(d))
    return c


def _phase2(best, best_score, deadline, t0):
    if time.process_time() - t0 < deadline:
        try:
            cons = _make_constraints()
            z0 = _to_z(best)
            z = _run_slsqp(z0, cons, 3000, 1e-14)
            arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
            arr = _exact_clean(arr)
            if _check_zero_tol(arr):
                sc = float(np.sum(arr[:, 2]))
                if sc > best_score:
                    return arr, sc
        except Exception:
            pass
    return best, best_score


def construct(budget_seconds, start):
    t0 = time.process_time()

    best = None
    best_score = -np.inf

    if start is not None:
        s = np.array(start, dtype=float)
        if s.shape == (N, 3) and _feasible_loose(s):
            s = _exact_clean(s)
            if _check_zero_tol(s):
                best = s
                best_score = float(np.sum(s[:, 2]))

    if best is None:
        best = _exact_clean(_fallback())
        best_score = float(np.sum(best[:, 2]))

    deadline = budget_seconds * 0.85

    # Phase 1: equality-constrained polish of the start's contact graph
    try:
        ap, aw = _find_active(best, tol=1e-9)
        cons_eq = _make_constraints(ap, aw)
        z0 = _to_z(best)
        z = _run_slsqp(z0, cons_eq, 3000, 1e-14)
        arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
        arr = _exact_clean(arr)
        if _check_zero_tol(arr):
            sc = float(np.sum(arr[:, 2]))
            if sc > best_score:
                best = arr
                best_score = sc
    except Exception:
        pass

    # Phase 2: inequality-only SLSQP polish
    best, best_score = _phase2(best, best_score, deadline, t0)

    # NEW: removal/reinsertion experiment
    if time.process_time() - t0 < deadline:
        try:
            c = _clearances(best)
            order = np.argsort(-c)[:5]
            rng = np.random.default_rng(777)
            # grid + random sample points
            gx = np.linspace(0.01, 0.99, 100)
            gX, gY = np.meshgrid(gx, gx)
            grid_pts = np.column_stack([gX.ravel(), gY.ravel()])
            rand_pts = rng.uniform(0.01, 0.99, size=(2000, 2))
            cand_pts = np.vstack([grid_pts, rand_pts])

            for idx in order:
                if time.process_time() - t0 >= deadline:
                    break
                others = np.delete(np.arange(N), idx)
                ox = best[others, 0]; oy = best[others, 1]; orr = best[others, 2]
                px = cand_pts[:, 0]; py = cand_pts[:, 1]
                # wall clearance
                wc = np.minimum(np.minimum(px, 1.0 - px), np.minimum(py, 1.0 - py))
                # min distance to others minus their radius
                dx = px[:, None] - ox[None, :]
                dy = py[:, None] - oy[None, :]
                d = np.sqrt(dx * dx + dy * dy) - orr[None, :]
                mc = np.min(d, axis=1)
                clr = np.minimum(wc, mc)
                k = int(np.argmax(clr))
                if clr[k] <= 1e-6:
                    continue
                cand = best.copy()
                cand[idx, 0] = px[k]
                cand[idx, 1] = py[k]
                cand[idx, 2] = clr[k]
                cand = _exact_clean(cand)
                if not _check_zero_tol(cand):
                    continue
                # Phase 2 polish
                try:
                    cons = _make_constraints()
                    z0 = _to_z(cand)
                    z = _run_slsqp(z0, cons, 3000, 1e-14)
                    arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
                    arr = _exact_clean(arr)
                    if _check_zero_tol(arr):
                        sc = float(np.sum(arr[:, 2]))
                        if sc > best_score:
                            best = arr
                            best_score = sc
                except Exception:
                    pass
        except Exception:
            pass

    # Phase 3: small random restarts with equality constraints on current active set
    rng = np.random.default_rng(12345)
    while time.process_time() - t0 < deadline:
        try:
            ap, aw = _find_active(best, tol=1e-9)
            cons_eq = _make_constraints(ap, aw)
            sigma = math.exp(rng.uniform(math.log(1e-4), math.log(1e-2)))
            cand = best.copy()
            cand[:, 0] += rng.normal(0.0, sigma, N)
            cand[:, 1] += rng.normal(0.0, sigma, N)
            cand[:, 2] += rng.normal(0.0, 0.5 * sigma, N)
            cand[:, 2] = np.maximum(cand[:, 2], 1e-6)
            cand[:, 0] = np.clip(cand[:, 0], cand[:, 2], 1.0 - cand[:, 2])
            cand[:, 1] = np.clip(cand[:, 1], cand[:, 2], 1.0 - cand[:, 2])
            z0 = _to_z(cand)
            z = _run_slsqp(z0, cons_eq, 3000, 1e-14)
            arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
            arr = _exact_clean(arr)
            if not _check_zero_tol(arr):
                continue
            sc = float(np.sum(arr[:, 2]))
            if sc > best_score:
                best = arr
                best_score = sc
        except Exception:
            continue

    best = _exact_clean(best)
    if not _check_zero_tol(best):
        best[:, 2] = np.maximum(best[:, 2] - 1e-7, 1e-9)
        best[:, 0] = np.clip(best[:, 0], best[:, 2], 1.0 - best[:, 2])
        best[:, 1] = np.clip(best[:, 1], best[:, 2], 1.0 - best[:, 2])
        best = _exact_clean(best)
    return best

import numpy as np
import time
import math
from scipy.optimize import minimize, root

N = 26


def _unpack(z):
    return z[0::3], z[1::3], z[2::3]


def _neg_sum(z):
    return -np.sum(z[2::3])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g[2::3] = -1.0
    return g


def _make_constraints(active_pairs=None, active_walls=None):
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def wall(z):
        x, y, r = _unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * N, 3 * N))
        for i in range(N):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[N + i, 3 * i] = -1.0; J[N + i, 3 * i + 2] = -1.0
            J[2 * N + i, 3 * i + 1] = 1.0; J[2 * N + i, 3 * i + 2] = -1.0
            J[3 * N + i, 3 * i + 1] = -1.0; J[3 * N + i, 3 * i + 2] = -1.0
        return J

    def pair(z):
        x, y, r = _unpack(z)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    def pair_jac(z):
        x, y, r = _unpack(z)
        J = np.zeros((len(pairs), 3 * N))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (r[i] + r[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
        return J

    cons = [
        {'type': 'ineq', 'fun': wall, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair, 'jac': pair_jac},
    ]

    if active_pairs:
        def apair(z):
            x, y, r = _unpack(z)
            out = np.empty(len(active_pairs))
            for k, (i, j) in enumerate(active_pairs):
                dx = x[i] - x[j]; dy = y[i] - y[j]
                out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
            return out

        def apair_jac(z):
            x, y, r = _unpack(z)
            J = np.zeros((len(active_pairs), 3 * N))
            for k, (i, j) in enumerate(active_pairs):
                dx = x[i] - x[j]; dy = y[i] - y[j]
                J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
                J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
                s = -2 * (r[i] + r[j])
                J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
            return J

        cons.append({'type': 'eq', 'fun': apair, 'jac': apair_jac})

    if active_walls:
        def awall(z):
            x, y, r = _unpack(z)
            out = np.empty(len(active_walls))
            for k, (i, kind) in enumerate(active_walls):
                if kind == 0:
                    out[k] = x[i] - r[i]
                elif kind == 1:
                    out[k] = 1.0 - x[i] - r[i]
                elif kind == 2:
                    out[k] = y[i] - r[i]
                else:
                    out[k] = 1.0 - y[i] - r[i]
            return out

        def awall_jac(z):
            J = np.zeros((len(active_walls), 3 * N))
            for k, (i, kind) in enumerate(active_walls):
                if kind == 0:
                    J[k, 3 * i] = 1.0; J[k, 3 * i + 2] = -1.0
                elif kind == 1:
                    J[k, 3 * i] = -1.0; J[k, 3 * i + 2] = -1.0
                elif kind == 2:
                    J[k, 3 * i + 1] = 1.0; J[k, 3 * i + 2] = -1.0
                else:
                    J[k, 3 * i + 1] = -1.0; J[k, 3 * i + 2] = -1.0
            return J

        cons.append({'type': 'eq', 'fun': awall, 'jac': awall_jac})

    return cons


def _run_slsqp(z0, cons, maxiter, ftol):
    try:
        res = minimize(_neg_sum, z0, jac=_neg_sum_grad, method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x
    except Exception:
        return z0


def _to_z(arr):
    z = np.empty(3 * N)
    z[0::3] = arr[:, 0]
    z[1::3] = arr[:, 1]
    z[2::3] = arr[:, 2]
    return z


def _exact_clean(arr):
    x = arr[:, 0].copy()
    y = arr[:, 1].copy()
    r = arr[:, 2].copy()
    r = np.maximum(r, 1e-9)
    for _ in range(8):
        m = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))
        for i in range(N):
            dx = x[i] - x
            dy = y[i] - y
            d = np.sqrt(dx * dx + dy * dy) - r
            d[i] = np.inf
            mi = np.min(d)
            if mi < m[i]:
                m[i] = mi
        r = np.minimum(r, m)
        r = np.nextafter(r, -np.inf)
        r = np.maximum(r, 1e-12)
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _check_zero_tol(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < 0) or np.any(x + r > 1):
        return False
    if np.any(y - r < 0) or np.any(y + r > 1):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                return False
    return True


def _feasible_loose(arr, tol=1e-7):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _fallback():
    k = int(np.ceil(np.sqrt(N)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
    return np.array([[x, y, 0.02] for x, y in pts])


def _find_active(arr, tol=1e-9):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    active_pairs = []
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = math.sqrt(dx * dx + dy * dy)
            gap = d - (r[i] + r[j])
            if gap < tol:
                active_pairs.append((i, j))
    active_walls = []
    for i in range(N):
        if x[i] - r[i] < tol:
            active_walls.append((i, 0))
        if 1.0 - x[i] - r[i] < tol:
            active_walls.append((i, 1))
        if y[i] - r[i] < tol:
            active_walls.append((i, 2))
        if 1.0 - y[i] - r[i] < tol:
            active_walls.append((i, 3))
    return active_pairs, active_walls


def _build_active_system(arr, slack_tol=1e-7):
    """Return (fun, jac) for active constraints and their Jacobian at arr."""
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    apairs = []
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = math.sqrt(dx * dx + dy * dy)
            gap = d - (r[i] + r[j])
            if gap < slack_tol:
                apairs.append((i, j))
    awalls = []
    for i in range(N):
        if x[i] - r[i] < slack_tol:
            awalls.append((i, 0))
        if 1.0 - x[i] - r[i] < slack_tol:
            awalls.append((i, 1))
        if y[i] - r[i] < slack_tol:
            awalls.append((i, 2))
        if 1.0 - y[i] - r[i] < slack_tol:
            awalls.append((i, 3))

    m = len(apairs) + len(awalls)

    def cfun(z):
        xx, yy, rr = _unpack(z)
        out = np.empty(m)
        k = 0
        for (i, j) in apairs:
            dx = xx[i] - xx[j]; dy = yy[i] - yy[j]
            out[k] = dx * dx + dy * dy - (rr[i] + rr[j]) ** 2
            k += 1
        for (i, kind) in awalls:
            if kind == 0:
                out[k] = xx[i] - rr[i]
            elif kind == 1:
                out[k] = 1.0 - xx[i] - rr[i]
            elif kind == 2:
                out[k] = yy[i] - rr[i]
            else:
                out[k] = 1.0 - yy[i] - rr[i]
            k += 1
        return out

    def cjac(z):
        xx, yy, rr = _unpack(z)
        J = np.zeros((m, 3 * N))
        k = 0
        for (i, j) in apairs:
            dx = xx[i] - xx[j]; dy = yy[i] - yy[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (rr[i] + rr[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
            k += 1
        for (i, kind) in awalls:
            if kind == 0:
                J[k, 3 * i] = 1.0; J[k, 3 * i + 2] = -1.0
            elif kind == 1:
                J[k, 3 * i] = -1.0; J[k, 3 * i + 2] = -1.0
            elif kind == 2:
                J[k, 3 * i + 1] = 1.0; J[k, 3 * i + 2] = -1.0
            else:
                J[k, 3 * i + 1] = -1.0; J[k, 3 * i + 2] = -1.0
            k += 1
        return J

    return cfun, cjac, m


def _kkt_solve(arr):
    """Solve KKT system at arr for active constraints. Returns new arr or None."""
    cfun, cjac, m = _build_active_system(arr, slack_tol=1e-7)
    if m == 0:
        return None
    z0 = _to_z(arr)
    g = _neg_sum_grad(z0)  # gradient of -sum r
    J0 = cjac(z0)
    # least squares for lambda: J^T lambda = -g
    try:
        lam0, *_ = np.linalg.lstsq(J0.T, -g, rcond=None)
    except Exception:
        return None
    n = 3 * N

    def F(w):
        z = w[:n]
        lam = w[n:]
        Jz = cjac(z)
        gz = _neg_sum_grad(z)
        top = gz + Jz.T @ lam
        bot = cfun(z)
        return np.concatenate([top, bot])

    w0 = np.concatenate([z0, lam0])
    try:
        sol = root(F, w0, method='hybr', tol=1e-14)
    except Exception:
        return None
    z = sol.x[:n]
    arr_new = np.column_stack([z[0::3], z[1::3], z[2::3]])
    return arr_new


def construct(budget_seconds, start):
    t0 = time.process_time()

    best = None
    best_score = -np.inf

    if start is not None:
        s = np.array(start, dtype=float)
        if s.shape == (N, 3) and _feasible_loose(s):
            s = _exact_clean(s)
            if _check_zero_tol(s):
                best = s
                best_score = float(np.sum(s[:, 2]))

    if best is None:
        best = _exact_clean(_fallback())
        best_score = float(np.sum(best[:, 2]))

    deadline = budget_seconds * 0.85

    # Phase 1: equality-constrained polish of the start's contact graph
    try:
        ap, aw = _find_active(best, tol=1e-9)
        cons_eq = _make_constraints(ap, aw)
        z0 = _to_z(best)
        z = _run_slsqp(z0, cons_eq, 3000, 1e-14)
        arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
        arr = _exact_clean(arr)
        if _check_zero_tol(arr):
            sc = float(np.sum(arr[:, 2]))
            if sc > best_score:
                best = arr
                best_score = sc
    except Exception:
        pass

    # Phase 2: inequality-only SLSQP polish
    if time.process_time() - t0 < deadline:
        try:
            cons = _make_constraints()
            z0 = _to_z(best)
            z = _run_slsqp(z0, cons, 3000, 1e-14)
            arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
            arr = _exact_clean(arr)
            if _check_zero_tol(arr):
                sc = float(np.sum(arr[:, 2]))
                if sc > best_score:
                    best = arr
                    best_score = sc
        except Exception:
            pass

    # Phase 3: small random restarts with equality constraints on current active set
    rng = np.random.default_rng(12345)
    while time.process_time() - t0 < deadline:
        try:
            ap, aw = _find_active(best, tol=1e-9)
            cons_eq = _make_constraints(ap, aw)
            sigma = math.exp(rng.uniform(math.log(1e-4), math.log(1e-2)))
            cand = best.copy()
            cand[:, 0] += rng.normal(0.0, sigma, N)
            cand[:, 1] += rng.normal(0.0, sigma, N)
            cand[:, 2] += rng.normal(0.0, 0.5 * sigma, N)
            cand[:, 2] = np.maximum(cand[:, 2], 1e-6)
            cand[:, 0] = np.clip(cand[:, 0], cand[:, 2], 1.0 - cand[:, 2])
            cand[:, 1] = np.clip(cand[:, 1], cand[:, 2], 1.0 - cand[:, 2])
            z0 = _to_z(cand)
            z = _run_slsqp(z0, cons_eq, 3000, 1e-14)
            arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
            arr = _exact_clean(arr)
            if not _check_zero_tol(arr):
                continue
            sc = float(np.sum(arr[:, 2]))
            if sc > best_score:
                best = arr
                best_score = sc
        except Exception:
            continue

    # Phase 4: KKT system solve at best, then one SLSQP polish
    if time.process_time() - t0 < deadline:
        try:
            arr_kkt = _kkt_solve(best)
            if arr_kkt is not None:
                arr_kkt = _exact_clean(arr_kkt)
                if _check_zero_tol(arr_kkt):
                    sc = float(np.sum(arr_kkt[:, 2]))
                    if sc > best_score:
                        best = arr_kkt
                        best_score = sc
                    # one Phase-2-style polish
                    if time.process_time() - t0 < deadline:
                        try:
                            cons = _make_constraints()
                            z0 = _to_z(best)
                            z = _run_slsqp(z0, cons, 3000, 1e-14)
                            arr = np.column_stack([z[0::3], z[1::3], z[2::3]])
                            arr = _exact_clean(arr)
                            if _check_zero_tol(arr):
                                sc2 = float(np.sum(arr[:, 2]))
                                if sc2 > best_score:
                                    best = arr
                                    best_score = sc2
                        except Exception:
                            pass
        except Exception:
            pass

    best = _exact_clean(best)
    if not _check_zero_tol(best):
        best[:, 2] = np.maximum(best[:, 2] - 1e-7, 1e-9)
        best[:, 0] = np.clip(best[:, 0], best[:, 2], 1.0 - best[:, 2])
        best[:, 1] = np.clip(best[:, 1], best[:, 2], 1.0 - best[:, 2])
        best = _exact_clean(best)
    return best

import numpy as np
import time
import math
from scipy.optimize import minimize

N = 26


def _unpack(z):
    return z[0::3], z[1::3], z[2::3]


def _neg_sum(z):
    return -np.sum(z[2::3])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g[2::3] = -1.0
    return g


def _neg_logsum(z):
    r = z[2::3]
    r = np.maximum(r, 1e-12)
    return -np.sum(np.log(r))


def _neg_logsum_grad(z):
    g = np.zeros_like(z)
    r = np.maximum(z[2::3], 1e-12)
    g[2::3] = -1.0 / r
    return g


def _make_constraints():
    pairs = [(i, j) for i in range(N) for j in range(i + 1, N)]

    def wall(z):
        x, y, r = _unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def wall_jac(z):
        J = np.zeros((4 * N, 3 * N))
        for i in range(N):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[N + i, 3 * i] = -1.0; J[N + i, 3 * i + 2] = -1.0
            J[2 * N + i, 3 * i + 1] = 1.0; J[2 * N + i, 3 * i + 2] = -1.0
            J[3 * N + i, 3 * i + 1] = -1.0; J[3 * N + i, 3 * i + 2] = -1.0
        return J

    def pair(z):
        x, y, r = _unpack(z)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    def pair_jac(z):
        x, y, r = _unpack(z)
        J = np.zeros((len(pairs), 3 * N))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            J[k, 3 * i] = 2 * dx; J[k, 3 * i + 1] = 2 * dy
            J[k, 3 * j] = -2 * dx; J[k, 3 * j + 1] = -2 * dy
            s = -2 * (r[i] + r[j])
            J[k, 3 * i + 2] = s; J[k, 3 * j + 2] = s
        return J

    return [
        {'type': 'ineq', 'fun': wall, 'jac': wall_jac},
        {'type': 'ineq', 'fun': pair, 'jac': pair_jac},
    ]


def _feasible(x, y, r, tol=1e-7):
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2 - tol:
                return False
    return True


def _run_slsqp(z0, cons, maxiter, ftol, fun=_neg_sum, jac=_neg_sum_grad):
    try:
        res = minimize(fun, z0, jac=jac, method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x
    except Exception:
        return z0


def _clean(z):
    x, y, r = _unpack(z)
    r = np.maximum(r, 0.0)
    r = r - 1e-9
    r = np.maximum(r, 1e-9)
    x = np.clip(x, r, 1 - r)
    y = np.clip(y, r, 1 - r)
    return np.column_stack([x, y, r])


def _to_z(arr):
    z = np.empty(3 * N)
    z[0::3] = arr[:, 0]
    z[1::3] = arr[:, 1]
    z[2::3] = arr[:, 2]
    return z


def _nextafter_down_slack_pass(arr):
    x = arr[:, 0].copy()
    y = arr[:, 1].copy()
    r = arr[:, 2].copy()
    for _ in range(12):
        m = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))
        for i in range(N):
            dx = x[i] - x
            dy = y[i] - y
            d = np.sqrt(dx * dx + dy * dy) - r
            d[i] = np.inf
            mi = np.min(d)
            if mi < m[i]:
                m[i] = mi
        r = np.minimum(r, m)
        r = np.nextafter(r, -np.inf)
        r = np.maximum(r, 1e-12)
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _check_zero_tol(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < 0) or np.any(x + r > 1):
        return False
    if np.any(y - r < 0) or np.any(y + r > 1):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                return False
    return True


def _violating_indices(arr):
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    bad = set()
    for i in range(N):
        if r[i] <= 0 or x[i] - r[i] < 0 or x[i] + r[i] > 1 \
                or y[i] - r[i] < 0 or y[i] + r[i] > 1:
            bad.add(i)
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            if dx * dx + dy * dy < (r[i] + r[j]) ** 2:
                bad.add(i); bad.add(j)
    return bad


def _repair(arr):
    result = _nextafter_down_slack_pass(arr)
    tries = 0
    while not _check_zero_tol(result) and tries < 30:
        bad = _violating_indices(result)
        if not bad:
            break
        for i in bad:
            result[i, 2] = np.nextafter(result[i, 2], -np.inf)
        result[:, 2] = np.maximum(result[:, 2], 1e-12)
        result = _nextafter_down_slack_pass(result)
        tries += 1
    return result


def _make_central_seeds():
    """Seeds: one large central circle + 25 small satellites on rings."""
    seeds = []
    for Rc in (0.16, 0.18, 0.20):
        for rsmall in (0.025, 0.032, 0.040):
            for inner_frac in (0.35, 0.45, 0.55):
                pts = [(0.5, 0.5, Rc)]
                n_in = 10
                r_in = inner_frac
                for k in range(n_in):
                    a = 2 * math.pi * k / n_in
                    pts.append((0.5 + r_in * math.cos(a),
                                0.5 + r_in * math.sin(a), rsmall))
                n_out = 15
                r_out = 0.5 - rsmall - 0.01
                for k in range(n_out):
                    a = 2 * math.pi * k / n_out + math.pi / n_out
                    pts.append((0.5 + r_out * math.cos(a),
                                0.5 + r_out * math.sin(a), rsmall))
                seeds.append(np.array(pts[:N]))
    for Rc in (0.16, 0.18, 0.20):
        for rsmall in (0.025, 0.032, 0.040):
            pts = [(0.5, 0.5, Rc)]
            d1 = 0.5 - rsmall - 0.01
            for k in range(6):
                a = math.pi / 3 * k
                pts.append((0.5 + d1 * math.cos(a), 0.5 + d1 * math.sin(a), rsmall))
            d2 = 0.5 - rsmall - 0.01
            for k in range(12):
                a = math.pi / 6 + math.pi / 6 * k
                pts.append((0.5 + d2 * math.cos(a), 0.5 + d2 * math.sin(a), rsmall))
            for k in range(6):
                a = math.pi / 3 * k + math.pi / 6
                pts.append((0.5 + 0.28 * math.cos(a), 0.5 + 0.28 * math.sin(a), rsmall))
            seeds.append(np.array(pts[:N]))
    return seeds


def _farthest_point_fill(fixed, n_fill, r_fill, rng):
    """Farthest-point sampling in [0.02,0.98]^2, rejecting overlaps with fixed."""
    pts = []
    fx = np.array([p[0] for p in fixed])
    fy = np.array([p[1] for p in fixed])
    fr = np.array([p[2] for p in fixed])
    # candidate grid
    g = np.linspace(0.02, 0.98, 40)
    cand = np.array([(x, y) for x in g for y in g])
    # reject candidates overlapping fixed
    keep = np.ones(len(cand), dtype=bool)
    for k in range(len(cand)):
        cx, cy = cand[k]
        dx = cx - fx; dy = cy - fy
        d2 = dx * dx + dy * dy
        if np.any(d2 < (fr + r_fill) ** 2):
            keep[k] = False
    cand = cand[keep]
    if len(cand) == 0:
        # fallback random
        for _ in range(n_fill):
            pts.append((rng.uniform(0.02, 0.98), rng.uniform(0.02, 0.98), r_fill))
        return pts
    chosen = [cand[rng.integers(len(cand))]]
    mind = np.full(len(cand), np.inf)
    for k in range(len(cand)):
        d = np.hypot(cand[k, 0] - chosen[0][0], cand[k, 1] - chosen[0][1])
        mind[k] = d
    for _ in range(n_fill - 1):
        idx = int(np.argmax(mind))
        chosen.append(cand[idx])
        for k in range(len(cand)):
            d = np.hypot(cand[k, 0] - cand[idx, 0], cand[k, 1] - cand[idx, 1])
            if d < mind[k]:
                mind[k] = d
    for c in chosen:
        pts.append((c[0], c[1], r_fill))
    return pts


def _make_three_dominant_seeds(rng):
    """Large central + two medium side circles + farthest-point fill."""
    seeds = []
    for r0 in (0.13, 0.14, 0.15):
        for r1 in (0.07, 0.08, 0.09):
            for rot in (0, 1):
                if rot == 0:
                    fixed = [(0.5, 0.5, r0),
                             (0.5 - (r0 + r1), 0.5, r1),
                             (0.5 + (r0 + r1), 0.5, r1)]
                else:
                    fixed = [(0.5, 0.5, r0),
                             (0.5, 0.5 - (r0 + r1), r1),
                             (0.5, 0.5 + (r0 + r1), r1)]
                # clip fixed into square
                ok = True
                for (x, y, r) in fixed:
                    if x - r < 0 or x + r > 1 or y - r < 0 or y + r > 1:
                        ok = False
                        break
                if not ok:
                    continue
                fill = _farthest_point_fill(fixed, N - 3, 0.04, rng)
                pts = fixed + fill
                seeds.append(np.array(pts[:N]))
    return seeds


def construct(budget_seconds, start):
    t0 = time.process_time()
    rng = np.random.default_rng(12345)
    seeds = _make_central_seeds() + _make_three_dominant_seeds(rng)
    cons = _make_constraints()

    best_out = None
    best_score = -np.inf

    # Seed best with start if available
    if start is not None:
        s = np.array(start, dtype=float)
        if _feasible(s[:, 0], s[:, 1], s[:, 2]):
            best_out = s.copy()
            best_score = np.sum(s[:, 2])

    for si, base in enumerate(seeds):
        if time.process_time() - t0 > budget_seconds * 0.75:
            break
        base = base.copy()
        base[:, 2] = np.maximum(base[:, 2], 1e-4)
        base[:, 0] = np.clip(base[:, 0], base[:, 2], 1 - base[:, 2])
        base[:, 1] = np.clip(base[:, 1], base[:, 2], 1 - base[:, 2])
        z0 = _to_z(base)

        z_log = _run_slsqp(z0, cons, 800, 1e-12,
                           fun=_neg_logsum, jac=_neg_logsum_grad)
        arr_log = _clean(z_log)

        z_sum = _run_slsqp(_to_z(arr_log), cons, 1200, 1e-10)
        out = _clean(z_sum)
        if _feasible(out[:, 0], out[:, 1], out[:, 2]):
            sc = np.sum(out[:, 2])
            if sc > best_score:
                best_score = sc
                best_out = out

        z_direct = _run_slsqp(z0, cons, 1200, 1e-10)
        out_d = _clean(z_direct)
        if _feasible(out_d[:, 0], out_d[:, 1], out_d[:, 2]):
            sc = np.sum(out_d[:, 2])
            if sc > best_score:
                best_score = sc
                best_out = out_d

    if best_out is None:
        k = int(np.ceil(np.sqrt(N)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:N]
        best_out = np.array([[x, y, 0.02] for x, y in pts])

    if time.process_time() - t0 < budget_seconds * 0.90:
        z_final = _run_slsqp(_to_z(best_out), cons, 800, 1e-14)
        arr_c = _clean(z_final)
        if _feasible(arr_c[:, 0], arr_c[:, 1], arr_c[:, 2]):
            if np.sum(arr_c[:, 2]) >= best_score:
                best_out = arr_c

    result = _repair(best_out)
    return result
